        )
      ).resolves.toBe(JSON.stringify({ value: 'dot' }, null, 2));
      await expect(
        readFile(
          join(
            outputDir,
            'services',
            'internal-fixture',
            'write-open-service-static-files',
            'rooted.json'
          ),
          'utf8'
        )
      ).resolves.toBe(JSON.stringify({ value: 'rooted' }, null, 2));
      await expect(
        readFile(
          join(
            outputDir,
            'services',
            'internal-fixture',
            'write-open-service-static-files',
            'windows',
            'style.json'
          ),
          'utf8'
        )
      ).resolves.toBe(JSON.stringify({ value: 'windows' }, null, 2));
    });
