import { mkdir, writeFile } from 'node:fs/promises';

import { dirname, join } from 'pathe';

import { toMerged } from 'es-toolkit/object';

import type { ServerCoreServices, TypedGetService } from './core-service-types.ts';
import {
  clearRegistry,
  describeService,
  getRegisteredServices,
  getService as getServiceCore,
  listServices,
  registerService as registerServiceCore,
  serviceRegistryApi,
} from './service-registry.ts';
import { createServiceRuntime, resolveStaticPath } from './service-runtime.ts';
import { validateSchema } from './service-validation.ts';
import type {
  AnyQueryDefinition,
  BuildTaskResult,
  Commands,
  Queries,
  ServiceDefinition,
  ServiceInstance,
  ServiceRegistrationOptions,
  ServiceRegistryApi,
  StaticStore,
} from './types.ts';

type RuntimeServiceDefinition = ServiceDefinition<unknown, Queries<unknown>, Commands<unknown>>;
type RuntimeQueryDefinition = AnyQueryDefinition<unknown>;

export const getService = getServiceCore as TypedGetService<ServerCoreServices>;

export { clearRegistry, describeService, getRegisteredServices, listServices };

/**
 * Registers a service on the dev server and returns its runtime surface.
 *
 * The server is a relay hub: when a channel is installed (the `services` preset does this on a real
 * websocket transport) it bridges every connected manager tab. Without a channel — static builds and
 * the index builder — the runtime stays local-only.
 */
export function registerService<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  definition: ServiceDefinition<TState, TQueries, TCommands>,
  registration?: ServiceRegistrationOptions<TState, TQueries, TCommands>
): ServiceInstance<TState, TQueries, TCommands> & ServiceRegistryApi {
  return registerServiceCore(definition, registration, { relay: true });
}

/**
 * Builds serialized static-state snapshots for `load`-enabled queries across every service
 * currently in the registry.
 *
 * Each static input runs against a fresh service runtime so one load path cannot leak state
 * into another path's snapshot. The runtime's `runLoadOnce` helper drives the load to completion
 * (including transitively triggered self-queries) before the resulting state is captured.
 * Cross-service `ctx.getService(...)` lookups inside a load resolve through the live registry,
 * matching dev-server behavior.
 */
export async function buildStaticFiles(): Promise<StaticStore> {
  const store: StaticStore = {};
  const buildTasks: Promise<BuildTaskResult[]>[] = [];

  for (const service of getRegisteredServices() as RuntimeServiceDefinition[]) {
    for (const [queryName, query] of Object.entries(service.queries) as [
      string,
      RuntimeQueryDefinition,
    ][]) {
      const { load, staticPath, staticInputs } = query;
      if (!staticPath || !load || !staticInputs) {
        continue;
      }

      buildTasks.push(
        (async () => {
          const inputsRuntime = createServiceRuntime(
            service,
            { registryApi: serviceRegistryApi },
            structuredClone(service.initialState)
          );
          const inputs = await staticInputs(inputsRuntime.loadCtxForStatic);

          return Promise.all(
            inputs.map(async (input) => {
              // Build every static input from a clean initial state so the serialized output mirrors
              // the one path this task is responsible for.
              const buildRuntime = createServiceRuntime(
                service,
                { registryApi: serviceRegistryApi },
                structuredClone(service.initialState)
              );
              const validatedInput = await validateSchema(query.input, input, {
                kind: 'query',
                serviceId: service.id,
                name: queryName,
                phase: 'input',
              });
              const path = resolveStaticPath(service.id, queryName, { staticPath }, validatedInput);

              await buildRuntime.runLoadOnce(queryName, validatedInput);

              return { path, state: buildRuntime.getStateSnapshot() };
            })
          );
        })()
      );
    }
  }

  const builtStates = (await Promise.all(buildTasks)).flat();

  for (const { path, state } of builtStates) {
    store[path] = path in store ? toMerged(store[path] as object, state as object) : state;
  }

  return store;
}

/**
 * Writes the registered services' static snapshots to `<outputDir>/services`.
 *
 * The snapshot keys are normalized slash-separated logical paths; splitting them here lets `join`
 * produce the correct native separators for the current operating system.
 */
export async function writeOpenServiceStaticFiles(outputDir: string): Promise<void> {
  const staticStore = await buildStaticFiles();

  await Promise.all(
    Object.entries(staticStore).map(async ([relativePath, state]) => {
      const outputPath = join(outputDir, 'services', ...relativePath.split('/'));

      await mkdir(dirname(outputPath), { recursive: true });
      await writeFile(outputPath, JSON.stringify(state, null, 2));
    })
  );
}

/**
 * Channel transport constants and helpers for the open-service peer-to-peer sync protocol.
 *
 * Services use Storybook's existing manager↔preview channel so that a service registered
 * in the manager or preview can automatically synchronise its state with other connected
 * peers. The `services:` prefix keeps service events trivially filterable from other
 * channel traffic.
 *
 * The live channel is read via {@link getChannel} from `storybook/internal/channels`.
 */
import { nanoid } from 'nanoid';
import * as v from 'valibot';

import type { ChannelLike } from '../../channels/types.ts';
import type { SerializedError } from './service-error-serialization.ts';

/**
 * Minimal channel contract needed for service sync.
 *
 * Structurally matches `Pick<ChannelLike, 'on' | 'off' | 'emit'>` so test mocks and the full
 * {@link Channel} class both satisfy this type.
 */
export type ServiceChannel = Pick<ChannelLike, 'on' | 'off' | 'emit'>;

export const SERVICE_SYNC_START = 'services:sync-start' as const;
export const SERVICE_SYNC_START_REPLY = 'services:sync-start-reply' as const;
export const SERVICE_PATCHES = 'services:patches' as const;
export const SERVICE_COMMAND_INVOKE = 'services:command-invoke' as const;
export const SERVICE_COMMAND_ACK = 'services:command-ack' as const;
export const SERVICE_COMMAND_RESULT = 'services:command-result' as const;
export const SERVICE_COMMAND_ERROR = 'services:command-error' as const;

/**
 * Channel payloads are untrusted input, so each event has a Valibot schema. Listeners narrow with
 * `v.safeParse(schema, payload)`; the payload *types* are derived from the schemas so the wire shape
 * and the static type can never drift. Field-level notes:
 *
 * - `state` must be a *plain* object: `v.record` accepts arrays, so a custom check rejects them
 *   (an array snapshot would corrupt the structural merge in `service-sync.ts`).
 * - `version` is a non-negative safe integer — the last-write-wins logical clock.
 * - `input` / `result` are optional: a `void` command input or output serializes to `undefined`,
 *   which JSON / telejson transports drop entirely, so the key is legitimately absent on the wire.
 */

/** A plain (non-array, non-null) object — the shape every synced state snapshot must take. */
const stateSnapshotSchema = v.custom<Record<string, unknown>>(
  (value) => typeof value === 'object' && value !== null && !Array.isArray(value)
);

/** Sent by a newly-registered peer to initialize its state from any existing peer. */
export const syncStartSchema = v.object({
  serviceId: v.string(),
  clientId: v.string(),
});
export type SyncStartPayload = v.InferOutput<typeof syncStartSchema>;

/**
 * A full state snapshot stamped for last-write-wins ordering. Shared by `services:patches` (broadcast
 * after every local command) and `services:sync-start-reply` (the response that bootstraps a freshly
 * registered peer). Recipients apply it only when it is strictly newer than their own (see `isNewer`
 * in `service-sync.ts`), which suppresses echoes, breaks relay cycles, and converges concurrent writes.
 */
export const stampedSnapshotSchema = v.object({
  serviceId: v.string(),
  state: stateSnapshotSchema,
  version: v.pipe(v.number(), v.safeInteger(), v.minValue(0)),
  clientId: v.string(),
});
export type StampedSnapshotPayload = v.InferOutput<typeof stampedSnapshotSchema>;
export type PatchesPayload = StampedSnapshotPayload;
export type SyncStartReplyPayload = StampedSnapshotPayload;

/**
 * Sent by a runtime that wants a command executed but has no local handler for it.
 *
 * Any peer that *does* implement the command runs it and replies with an ack, then a result or
 * error carrying the same `callId`. The requester awaits its promise until one of those arrives.
 * `input` is the raw (unvalidated) command input; the implementing peer validates it before running.
 */
export const commandInvokeSchema = v.object({
  serviceId: v.string(),
  commandName: v.string(),
  input: v.optional(v.unknown()),
  callId: v.string(),
  clientId: v.string(),
});
export type CommandInvokePayload = v.InferOutput<typeof commandInvokeSchema>;

/**
 * Emitted by an implementing peer the moment it accepts a `services:command-invoke`.
 *
 * Requesters use this to detect that at least one peer will run the command; if no ack arrives
 * within a short window, the request rejects as unhandled. The requester still resolves/rejects on
 * the result/error reply once a peer has acknowledged.
 */
export const commandAckSchema = v.object({
  serviceId: v.string(),
  callId: v.string(),
  clientId: v.string(),
});
export type CommandAckPayload = v.InferOutput<typeof commandAckSchema>;

/** Sent by an implementing peer after a remote command resolves successfully. */
export const commandResultSchema = v.object({
  serviceId: v.string(),
  callId: v.string(),
  result: v.optional(v.unknown()),
  clientId: v.string(),
});
export type CommandResultPayload = v.InferOutput<typeof commandResultSchema>;

/**
 * Sent by an implementing peer after a remote command throws. `error` is a serialized error
 * (including its `cause` chain) so the requester can rethrow a real `Error`; it is only checked for
 * "is a plain object" here and reconstructed in `service-error-serialization.ts`.
 */
export const commandErrorSchema = v.object({
  serviceId: v.string(),
  callId: v.string(),
  error: v.custom<SerializedError>(
    (value) => typeof value === 'object' && value !== null && !Array.isArray(value)
  ),
  clientId: v.string(),
});
export type CommandErrorPayload = v.InferOutput<typeof commandErrorSchema>;

/**
 * Generates a unique id for one runtime instance (and for one remote-command `callId`).
 *
 * The id is identity-critical: it is the last-write-wins tiebreak for equal versions, the loop guard
 * that drops a peer's own echoes, and the correlation key matching command replies to their calls.
 * `nanoid` is used (over `Math.random`) so collisions cannot silently break that determinism.
 */
export function generateClientId(): string {
  return nanoid();
}

/**
 * Tests for remote command execution: a runtime without a local handler requests execution from a
 * peer, and a runtime that has one responds. The protocol (`service-transport.ts`) is documented on
 * {@link connectCommandTransport}.
 *
 * Peers are simulated with the test channel's `emitExternal`, the same approach the sync tests use.
 */
import * as v from 'valibot';
import { afterEach, describe, expect, it, onTestFinished, vi } from 'vitest';

import {
  awaitedPreloadValueServiceDef,
  entryIdInputSchema,
  mutableRecordLookupServiceDef,
  preloadedValueOutputSchema,
  voidOutputSchema,
} from './fixtures.ts';
import { defineService } from './service-definition.ts';
import {
  SERVICE_COMMAND_ACK,
  SERVICE_COMMAND_ERROR,
  SERVICE_COMMAND_INVOKE,
  SERVICE_COMMAND_RESULT,
  SERVICE_PATCHES,
  type CommandErrorPayload,
  type CommandInvokePayload,
} from './service-channel.ts';
import { deserializeError } from './service-error-serialization.ts';
import { clearRegistry, registerService, unregisterService } from './service-registry.ts';
import { REMOTE_COMMAND_ACK_TIMEOUT_MS } from './service-transport.ts';
import { createTestChannel, installTestChannel } from '../../channels/test-channel.ts';

const remoteOnlyServiceDef = defineService({
  id: 'internal-fixture/remote-only-command',
  description: 'Declares a command with no local handler so it must run remotely.',
  initialState: {} as Record<string, never>,
  queries: {},
  commands: {
    doThing: {
      description: 'Has no local handler in this runtime.',
      input: v.object({ value: v.string() }),
      output: v.string(),
    },
  },
});

const throwingCommandServiceDef = defineService({
  id: 'internal-fixture/throwing-command',
  description: 'Implements a command that always throws, to exercise error replies.',
  initialState: {} as Record<string, never>,
  queries: {},
  commands: {
    boom: {
      description: 'Throws an error with a cause.',
      input: v.object({}),
      output: v.void(),
      handler: async () => {
        throw new Error('kaboom', { cause: new Error('root cause') });
      },
    },
  },
});

/** Query `load` invokes a command that has no handler in this runtime (peer-only). */
const loadInvokesRemoteCommandServiceDef = defineService({
  id: 'internal-fixture/load-invokes-remote-command',
  description: 'Query load calls a command declared without a local handler.',
  initialState: {} as Record<string, string | undefined>,
  queries: {
    preloadedValue: {
      description: 'Populates state via a remote-only command inside load.',
      input: entryIdInputSchema,
      output: preloadedValueOutputSchema,
      handler: (input, ctx) => ctx.self.state[input.entryId] ?? null,
      load: (input, ctx) => ctx.self.commands.preloadValue(input).then(() => undefined),
    },
  },
  commands: {
    preloadValue: {
      description: 'Populates one entry — implemented only on a peer in this test runtime.',
      input: entryIdInputSchema,
      output: voidOutputSchema,
    },
  },
});

function emittedCalls(channel: ReturnType<typeof createTestChannel>, event: string) {
  return channel.emit.mock.calls.filter(([name]) => name === event);
}

afterEach(() => {
  vi.useRealTimers();
  clearRegistry();
  installTestChannel(null);
});

describe('remote command requester (no local handler)', () => {
  it('emits a command-invoke envelope when the command is called', () => {
    const channel = createTestChannel();
    installTestChannel(channel);

    const service = registerService(remoteOnlyServiceDef);
    service.commands.doThing({ value: 'hi' }).catch(() => {});

    const invokes = emittedCalls(channel, SERVICE_COMMAND_INVOKE);
    expect(invokes).toHaveLength(1);
    expect(invokes[0][1]).toMatchObject({
      serviceId: remoteOnlyServiceDef.id,
      commandName: 'doThing',
      input: { value: 'hi' },
      callId: expect.any(String),
      clientId: expect.any(String),
    });

    unregisterService(remoteOnlyServiceDef.id);
  });

  it('resolves with the result of the matching command-result reply', async () => {
    const channel = createTestChannel();
    installTestChannel(channel);

    const service = registerService(remoteOnlyServiceDef);
    const promise = service.commands.doThing({ value: 'hi' });

    const { callId } = emittedCalls(channel, SERVICE_COMMAND_INVOKE)[0][1] as CommandInvokePayload;
    channel.emitExternal(SERVICE_COMMAND_RESULT, {
      serviceId: remoteOnlyServiceDef.id,
      callId,
      result: 'done',
      clientId: 'peer',
    });

    await expect(promise).resolves.toBe('done');
  });

  it('rejects with the reconstructed error from a command-error reply', async () => {
    const channel = createTestChannel();
    installTestChannel(channel);

    const service = registerService(remoteOnlyServiceDef);
    const promise = service.commands.doThing({ value: 'hi' });

    const { callId } = emittedCalls(channel, SERVICE_COMMAND_INVOKE)[0][1] as CommandInvokePayload;
    channel.emitExternal(SERVICE_COMMAND_ERROR, {
      serviceId: remoteOnlyServiceDef.id,
      callId,
      clientId: 'peer',
      error: {
        __openServiceError__: true,
        name: 'OpenServiceValidationError',
        message: 'invalid input',
        properties: { fromStorybook: true, code: 5 },
      },
    });

    await expect(promise).rejects.toMatchObject({
      message: 'invalid input',
      fromStorybook: true,
      code: 5,
    });
  });

  it('keeps only the first reply when several peers answer one call', async () => {
    const channel = createTestChannel();
    installTestChannel(channel);

    const service = registerService(remoteOnlyServiceDef);
    const promise = service.commands.doThing({ value: 'hi' });

    const { callId } = emittedCalls(channel, SERVICE_COMMAND_INVOKE)[0][1] as CommandInvokePayload;
    channel.emitExternal(SERVICE_COMMAND_RESULT, {
      serviceId: remoteOnlyServiceDef.id,
      callId,
      result: 'first',
      clientId: 'peer-1',
    });
    // A later reply for the same call (a second implementer) must be ignored, not throw.
    expect(() =>
      channel.emitExternal(SERVICE_COMMAND_RESULT, {
        serviceId: remoteOnlyServiceDef.id,
        callId,
        result: 'second',
        clientId: 'peer-2',
      })
    ).not.toThrow();

    await expect(promise).resolves.toBe('first');
  });

  it('ignores replies addressed to a different service or an unknown call', async () => {
    const channel = createTestChannel();
    installTestChannel(channel);

    const service = registerService(remoteOnlyServiceDef);
    const promise = service.commands.doThing({ value: 'hi' });

    const { callId } = emittedCalls(channel, SERVICE_COMMAND_INVOKE)[0][1] as CommandInvokePayload;
    channel.emitExternal(SERVICE_COMMAND_RESULT, {
      serviceId: 'some/other-service',
      callId,
      result: 'wrong-service',
      clientId: 'peer',
    });
    channel.emitExternal(SERVICE_COMMAND_RESULT, {
      serviceId: remoteOnlyServiceDef.id,
      callId: 'unknown-call',
      result: 'wrong-call',
      clientId: 'peer',
    });
    channel.emitExternal(SERVICE_COMMAND_RESULT, {
      serviceId: remoteOnlyServiceDef.id,
      callId,
      result: 'correct',
      clientId: 'peer',
    });

    await expect(promise).resolves.toBe('correct');
  });

  it('rejects when no peer acknowledges the invoke within the timeout', async () => {
    vi.useFakeTimers();

    const channel = createTestChannel();
    installTestChannel(channel);

    const service = registerService(remoteOnlyServiceDef);
    const promise = service.commands.doThing({ value: 'hi' });
    const assertion = expect(promise).rejects.toThrow(
      'No runtime acknowledged remote command "internal-fixture/remote-only-command.doThing"; its handler is not implemented in any connected runtime.'
    );

    await vi.advanceTimersByTimeAsync(REMOTE_COMMAND_ACK_TIMEOUT_MS);
    await assertion;
  });

  it('does not reject after a peer acknowledges the invoke', async () => {
    vi.useFakeTimers();

    const channel = createTestChannel();
    installTestChannel(channel);

    const service = registerService(remoteOnlyServiceDef);
    const promise = service.commands.doThing({ value: 'hi' });

    const { callId } = emittedCalls(channel, SERVICE_COMMAND_INVOKE)[0][1] as CommandInvokePayload;
    channel.emitExternal(SERVICE_COMMAND_ACK, {
      serviceId: remoteOnlyServiceDef.id,
      callId,
      clientId: 'peer',
    });

    await vi.advanceTimersByTimeAsync(REMOTE_COMMAND_ACK_TIMEOUT_MS);

    channel.emitExternal(SERVICE_COMMAND_RESULT, {
      serviceId: remoteOnlyServiceDef.id,
      callId,
      result: 'done',
      clientId: 'peer',
    });

    await expect(promise).resolves.toBe('done');
  });

  it('rejects in-flight remote calls when the service is unregistered', async () => {
    const channel = createTestChannel();
    installTestChannel(channel);

    const service = registerService(remoteOnlyServiceDef);
    const promise = service.commands.doThing({ value: 'hi' });

    unregisterService(remoteOnlyServiceDef.id);

    await expect(promise).rejects.toThrow(/unregistered before a remote command resolved/);
  });
});

describe('remote command responder (has local handler)', () => {
  it('acknowledges, runs the command, broadcasts state, and replies with the result', async () => {
    const channel = createTestChannel();
    installTestChannel(channel);

    const service = registerService(mutableRecordLookupServiceDef);

    channel.emitExternal(SERVICE_COMMAND_INVOKE, {
      serviceId: mutableRecordLookupServiceDef.id,
      commandName: 'assignRecordField',
      input: { entryId: 'a', fieldKey: 'k', fieldValue: 'v' },
      callId: 'call-1',
      clientId: 'requester',
    });

    // The ack is emitted synchronously on receipt, before the command runs.
    expect(channel.emit).toHaveBeenCalledWith(
      SERVICE_COMMAND_ACK,
      expect.objectContaining({
        serviceId: mutableRecordLookupServiceDef.id,
        callId: 'call-1',
        clientId: expect.any(String),
      })
    );

    await vi.waitFor(() =>
      expect(channel.emit).toHaveBeenCalledWith(
        SERVICE_COMMAND_RESULT,
        expect.objectContaining({ callId: 'call-1', serviceId: mutableRecordLookupServiceDef.id })
      )
    );

    expect(service.queries.recordFields.get({ entryId: 'a' })).toEqual({ k: 'v' });
    expect(emittedCalls(channel, SERVICE_PATCHES).length).toBeGreaterThan(0);
  });

  it('replies with a serialized error (including the cause) when the handler throws', async () => {
    const channel = createTestChannel();
    installTestChannel(channel);

    registerService(throwingCommandServiceDef);

    channel.emitExternal(SERVICE_COMMAND_INVOKE, {
      serviceId: throwingCommandServiceDef.id,
      commandName: 'boom',
      input: {},
      callId: 'call-err',
      clientId: 'requester',
    });

    await vi.waitFor(() => expect(emittedCalls(channel, SERVICE_COMMAND_ERROR)).toHaveLength(1));

    const payload = emittedCalls(channel, SERVICE_COMMAND_ERROR)[0][1] as CommandErrorPayload;
    expect(payload).toMatchObject({ serviceId: throwingCommandServiceDef.id, callId: 'call-err' });

    const restored = deserializeError(payload.error);
    expect(restored.message).toBe('kaboom');
    expect((restored.cause as Error).message).toBe('root cause');
  });

  it('ignores invokes for commands it does not implement', async () => {
    const channel = createTestChannel();
    installTestChannel(channel);

    // This runtime has no local handler for `doThing`, so it must not answer the invoke.
    registerService(remoteOnlyServiceDef);

    channel.emitExternal(SERVICE_COMMAND_INVOKE, {
      serviceId: remoteOnlyServiceDef.id,
      commandName: 'doThing',
      input: { value: 'hi' },
      callId: 'call-unhandled',
      clientId: 'requester',
    });

    await new Promise<void>((resolve) => setTimeout(resolve, 10));

    expect(emittedCalls(channel, SERVICE_COMMAND_ACK)).toHaveLength(0);
    expect(emittedCalls(channel, SERVICE_COMMAND_RESULT)).toHaveLength(0);
  });
});

describe('load bodies and command routing', () => {
  it('calls the local command handler from a load body without emitting command-invoke', async () => {
    const channel = createTestChannel();
    installTestChannel(channel);
    const handlerSpy = vi.spyOn(awaitedPreloadValueServiceDef.commands.preloadValue, 'handler');
    onTestFinished(() => {
