            handler: (_input, ctx) => ctx.self.state.value,
          },
        },
        commands: {
          setValue: {
            input: v.number(),
            output: v.void(),
            handler: (next, ctx) =>
              ctx.self.setState((state) => {
                state.value = next;
              }),
