  /**
   * `buildStaticFiles()` drives each snapshot through `runLoadOnce`. Load bodies normally pull
   * dependencies via `ctx.self.queries.*`; those reads run `triggerLoad` during the synchronous
   * prefix (before the first `await`). The root `runLoadOnce` load must therefore appear in the
   * process-global in-flight map before the body starts, same as dev-server `.loaded()` does via
   * `triggerLoad`. Otherwise a read that resolves to the same load key — including a deliberate
   * same-query re-read or a short cycle back to the running query — starts a second `runLoadBody`
   * and can double-apply command side effects in static output.
   *
   * The test below uses a same-query re-read as the smallest repro; reading other queries in the
   * sync prefix is common too, but only same-key (or cyclic) paths hit this duplicate.
   */
  describe('runLoadOnce (static snapshot loads)', () => {
    it('registers the root load so a synchronous self.queries re-read does not refire the load body', async () => {
      const queryName = 'value';
      const loadBodySpy = vi.fn();
      const bumpCommandSpy = vi.fn();

      const staticSnapshotServiceDef = defineService({
        id: 'internal-fixture/run-load-once-sync-self-read',
        description:
          'Static build fixture: load reads its own query through wrapped self.queries before awaiting.',
        initialState: { count: 0 },
        queries: {
          [queryName]: {
            input: v.undefined(),
            output: v.number(),
            handler: (_input, ctx) => ctx.self.state.count,
            load: async (_input, ctx) => {
              loadBodySpy();
              // Mirrors static snapshot loads: sync handler read before the first await.
              ctx.self.queries[queryName].get(undefined);
              await ctx.self.commands.bump(undefined);
            },
          },
        },
        commands: {
          bump: {
            input: v.undefined(),
            output: v.void(),
            handler: (_input, ctx) => {
              bumpCommandSpy();
              ctx.self.setState((state) => {
                state.count += 1;
              });
            },
          },
        },
      });

      const buildRuntime = createServiceRuntime(staticSnapshotServiceDef, {
        registryApi: serviceRegistryApi,
      });

      await buildRuntime.runLoadOnce(queryName, undefined);

      // A duplicate load body would run bump twice and leave count at 2.
      expect(buildRuntime.getStateSnapshot().count).toBe(1);
      expect(loadBodySpy).toHaveBeenCalledTimes(1);
      expect(bumpCommandSpy).toHaveBeenCalledTimes(1);
    });
  });

  // The `subscriptions`/`reactive load` suites assert the emitted *data* sequence (via collectData).
  // This suite asserts the orthogonal axis: the per-subscription `QueryState` lifecycle that wraps
  // that data (status / loadStatus / error and the derived booleans).
  describe('query state lifecycle', () => {
    it('reports success/idle immediately for a query with no load', () => {
      const service = registerService(mutableRecordLookupServiceDef);
      const states: Array<QueryState<unknown>> = [];

      const unsubscribe = service.queries.recordFields.subscribe(
        { entryId: 'entry-a' },
        (state) => {
          states.push(state);
        }
      );

      // A no-load query emits its success/idle state synchronously during subscribe() — no waitFor.
      expect(states).toHaveLength(1);
      expect(states[0]).toMatchObject({
        data: null,
        error: undefined,
        status: 'success',
        loadStatus: 'idle',
        isSuccess: true,
        isPending: false,
        isError: false,
        isLoading: false,
        isInitialLoading: false,
        isRefreshing: false,
      });

      unsubscribe();
    });

    it('transitions pending → success as a load settles', async () => {
      const service = registerService(awaitedPreloadValueServiceDef);
      const states: Array<QueryState<unknown>> = [];

      const unsubscribe = service.queries.preloadedValue.subscribe(
        { entryId: 'entry-a' },
        (state) => {
          states.push(state);
        }
      );

      // The first emission, before the load settles, is the initial load over no data yet. It is
      // emitted synchronously during subscribe() (the reactive-load effect runs synchronously and
      // the first emission already reads `loading`), so it is observable without waiting.
      expect(states).toHaveLength(1);
      expect(states[0]).toMatchObject({
        data: null,
        status: 'pending',
        loadStatus: 'loading',
        isPending: true,
        isRefreshing: false,
      });

      // Once the load resolves, the subscription is success/idle with the loaded data.
      await vi.waitFor(() => {
        const last = states[states.length - 1];
        expect(last).toMatchObject({
          data: 'preloaded',
          status: 'success',
          loadStatus: 'idle',
          isSuccess: true,
          isLoading: false,
          isInitialLoading: false,
        });
      });

      unsubscribe();
    });

    it('reports isInitialLoading only while there is no data yet, not over cached data', async () => {
      // Models a real load-backed query (like docgen/story-docs): the handler returns `undefined`
      // until the load populates state, and the populated value persists in state afterwards.
      const cachedDef = defineService({
        id: 'internal-fixture/lifecycle-initial-loading',
        description:
          'Load-backed query whose handler returns undefined until the load populates it.',
        initialState: { value: undefined as string | undefined },
        queries: {
          value: {
            input: v.undefined(),
            output: v.optional(v.string()),
            handler: (_input, ctx) => ctx.self.state.value,
            load: async (_input, ctx) => {
              await ctx.self.commands.setValue('loaded');
            },
          },
        },
        commands: {
          setValue: {
            input: v.string(),
            output: v.void(),
            handler: (next, ctx) =>
              ctx.self.setState((state) => {
                state.value = next;
              }),
          },
        },
      });
      const service = registerService(cachedDef);

      // First subscription: no data yet, so the in-flight first load is a genuine initial load.
      const firstStates: Array<QueryState<unknown>> = [];
      const unsubscribeFirst = service.queries.value.subscribe(undefined, (state) => {
        firstStates.push(state);
      });
      expect(firstStates[0]).toMatchObject({
        data: undefined,
        status: 'pending',
        loadStatus: 'loading',
        isInitialLoading: true,
      });
      await vi.waitFor(() => {
        expect(firstStates[firstStates.length - 1]).toMatchObject({
          data: 'loaded',
          status: 'success',
          isInitialLoading: false,
        });
      });
      unsubscribeFirst();

      // Second subscription, now that the value is cached: the per-subscription lifecycle still
      // starts pending/loading, but `data` is already present from the first emission, so this must
      // NOT report an initial load — consumers must not flash a skeleton over already-available data.
      const secondStates: Array<QueryState<unknown>> = [];
      const unsubscribeSecond = service.queries.value.subscribe(undefined, (state) => {
        secondStates.push(state);
      });
      expect(secondStates[0]).toMatchObject({
        data: 'loaded',
        loadStatus: 'loading',
        isInitialLoading: false,
      });
      unsubscribeSecond();
    });

    it('transitions to error when the load rejects, keeping the last data', async () => {
      const failingDef = defineService({
        id: 'internal-fixture/lifecycle-load-reject',
        description:
          'Loads successfully once, then rejects on a re-load to exercise error-state data retention.',
        initialState: { value: null as string | null, failNext: false },
        queries: {
          value: {
            input: v.undefined(),
            output: v.nullable(v.string()),
            handler: (_input, ctx) => ctx.self.state.value,
            load: async (_input, ctx) => {
              // Tracked read: flipping `failNext` re-fires this load, which then rejects.
              if (ctx.self.state.failNext) {
                throw new Error('boom');
              }
              await ctx.self.commands.setValue('loaded');
            },
          },
        },
        commands: {
          setValue: {
            input: v.nullable(v.string()),
            output: v.void(),
            handler: (next, ctx) =>
              ctx.self.setState((state) => {
                state.value = next;
              }),
          },
          setFailNext: {
            input: v.boolean(),
            output: v.void(),
            handler: (next, ctx) =>
              ctx.self.setState((state) => {
                state.failNext = next;
              }),
          },
        },
      });
      const service = registerService(failingDef);
      const states: Array<QueryState<unknown>> = [];

      const unsubscribe = service.queries.value.subscribe(undefined, (state) => {
        states.push(state);
      });

      // The first load succeeds and populates the data.
      await vi.waitFor(() => {
        const last = states[states.length - 1];
        expect(last).toMatchObject({ data: 'loaded', status: 'success', loadStatus: 'idle' });
      });

      // Flipping the tracked dependency re-fires the load, which now rejects. The resulting error
      // state must retain the previously-loaded `data` rather than dropping it to undefined/null.
      await service.commands.setFailNext(true);
      await vi.waitFor(() => {
        const last = states[states.length - 1];
        expect(last.status).toBe('error');
      });
      const last = states[states.length - 1];
      expect(last).toMatchObject({
        data: 'loaded',
        status: 'error',
        loadStatus: 'idle',
        isError: true,
        isLoading: false,
      });
      expect(last.error?.message).toBe('boom');

      unsubscribe();
    });

    it('reports isRefreshing on a background re-load over existing data', async () => {
      const reactiveDef = defineService({
        id: 'internal-fixture/lifecycle-reactive-refresh',
        initialState: { source: 1, derived: null as number | null },
        queries: {
          derived: {
            input: v.void(),
            output: v.nullable(v.number()),
            handler: (_input, ctx) => ctx.self.state.derived,
            load: async (_input, ctx) => {
              const source = ctx.self.state.source;
              await Promise.resolve();
              await ctx.self.commands.setDerived(source * 10);
            },
          },
        },
        commands: {
          setSource: {
            input: v.number(),
            output: v.void(),
            handler: (next, ctx) =>
              ctx.self.setState((state) => {
                state.source = next;
              }),
          },
          setDerived: {
            input: v.number(),
            output: v.void(),
            handler: (next, ctx) =>
              ctx.self.setState((state) => {
                state.derived = next;
              }),
          },
        },
      });
      const service = registerService(reactiveDef);
      const states: Array<QueryState<unknown>> = [];

      const unsubscribe = service.queries.derived.subscribe(undefined, (state) => {
        states.push(state);
      });

      // Wait for the initial load to settle to success.
      await vi.waitFor(() => {
        const last = states[states.length - 1];
        expect(last).toMatchObject({ data: 10, status: 'success', loadStatus: 'idle' });
      });

      // Changing the load's dependency re-fires it over the existing data: status stays success
      // while loadStatus flips to loading — a background refresh, not an initial load.
      await service.commands.setSource(5);
      await vi.waitFor(() =>
        expect(
          states.some(
            (state) =>
              state.isRefreshing &&
              state.status === 'success' &&
              state.loadStatus === 'loading' &&
              state.isInitialLoading === false
          )
        ).toBe(true)
      );

      // The refresh settles back to success/idle with the new value.
      await vi.waitFor(() => {
        const last = states[states.length - 1];
        expect(last).toMatchObject({ data: 50, status: 'success', loadStatus: 'idle' });
      });

      unsubscribe();
    });
  });
});

/**
 * # service-runtime
 *
 * Builds the runtime surface for one registered service: state signal, sync queries with
 * `.loaded()` and `.subscribe()`, async commands, and the in-flight load registry that powers
 * dependency tracking for `.loaded()`.
 *
 * ## Mental model in one paragraph
 *
 * `query.get(input)` is a synchronous, pure read: it validates input, calls the handler against
 * current state, and returns the result immediately. It does **not** fire the query's `load` — a
 * read never starts background work. Loads fire only through `query.subscribe(...)` (reactively,
 * re-firing as tracked state changes) and `query.loaded(input)` (the "wait until fully loaded"
 * form). `.loaded()` must guarantee that **every dependency the handler transitively reads is
 * settled** before returning, even though those dependencies are not declared statically anywhere.
 * That guarantee is what the drain machinery in this file exists to provide. When a handler or load
 * body reads a *dependency* via `.get()` inside a `.loaded()` drain or a load body, that read still
 * triggers and awaits the dependency's load; a bare consumer `.get()` does not.
 *
 * ## Dependency-tracking algorithm
 *
 * `.loaded()` runs a *drain loop*:
 *
 * 1. Fire this query's own `load` and put the promise into a `LoadedSession` collector.
 * 2. Repeat:
 *    - Await everything currently in the collector with `Promise.allSettled`.
 *    - Mark those load keys as `settled` for the session.
 *    - Run the sync handler under the session as a *discovery pass*. Every sync read of a
 *      dependency query (via `ctx.self.queries.*` or `ctx.getService(...).queries.*`) consults
 *      the module-scoped `activeHandlerLoadSession`; if that dep's load is not already
 *      settled or on the ancestor chain, its promise is added to the collector.
 *    - If the discovery pass added new entries, loop again. Otherwise, exit.
 * 3. Final handler call (no session) returns the validated output.
 *
 * Inside a `load` body, `ctx.self.queries.*` are *wrapped* by {@link buildLoadWrappedQueries} so
 * the same registration happens against a load-local collector — the load promise only resolves
 * when its body **and** its own dependencies have settled. This propagates the "wait" through
 * async load bodies without needing AsyncLocalStorage.
 *
 * ## Why each piece exists
 *
 * - **{@link inFlightLoads}** dedups concurrent calls for the same `(service, query, input)` so
 *   two consumers asking for the same data share one load.
 * - **{@link LoadedSession.ancestorChain}** breaks cycles: a dep whose load key is already on the
 *   call chain is skipped (not added to any collector) so two queries that read each other do
 *   not self-deadlock.
 * - **{@link LoadedSession.settledKeys}** prevents the discovery loop from refiring already
 *   completed loads on each iteration — without it, every reread of a dep in the handler would
 *   re-trigger its load and the drain loop would never converge.
 * - **{@link MAX_DRAIN_ITERATIONS}** caps pathological cases (e.g. a handler reading a query with
 *   an ever-changing input key) so a buggy service surfaces a real error instead of hanging.
 *
 * ## Boundaries
 *
 * Cross-service `getService(...).queries.*` calls **inside a load body** are intentionally not
 * tracked into the load-local collector. Authors who need cross-service deps awaited from inside
 * a load should call `.loaded()` explicitly (e.g. `await ctx.getService(id).queries.foo
 * .loaded(input)`). Cross-service calls from a sync handler still go through the session-aware
 * path because handler reads are tracked by `activeHandlerLoadSession`, which is module-scoped
 * and stable for the duration of a sync handler call.
 */
import { batch } from '@preact/signals-core';
import { deepSignal } from 'deepsignal/core';

import {
  OpenServiceInvalidStaticPathError,
  OpenServiceUnimplementedOperationError,
} from '../../server-errors.ts';
import {
  buildQueries,
  buildReactiveLoadQueries,
  inFlightLoads,
  makeLoadKey,
  runLoadBody,
} from './query-runtime.ts';
import type { QueryRuntimeRefs, RuntimeQueryDefinition } from './query-runtime.ts';
import { applyStatePatch } from './service-sync.ts';
import { validateSchema } from './service-validation.ts';
import type { StaticLoader } from './static-fetch.ts';
import type {
  Command,
  CommandCtx,
  CommandSelf,
  Commands,
  LoadCtx,
  LoadSelf,
  Queries,
  Query,
  QueryCtx,
  QuerySelf,
  RuntimeService,
  ServiceDefinition,
  ServiceId,
  ServiceInstance,
  ServiceRegistryApi,
} from './types.ts';

/**
 * Internal runtime object returned while a service instance is being assembled.
 *
 * It keeps the raw signal and `self` reference available for static building and registration so
 * callers can capture the post-load state snapshot without rebuilding the runtime.
 */
export type ServiceRuntime<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
> = {
  /** Returns a plain, detached snapshot of the current state for serialization. */
  getStateSnapshot(): TState;
  commandSelf: CommandSelf<TState>;
  queryCtx: QueryCtx<TState>;
  loadCtxForStatic: LoadCtx<TState>;
  commands: ServiceInstance<TState, TQueries, TCommands>['commands'];
  queries: ServiceInstance<TState, TQueries, TCommands>['queries'];
  runLoadOnce(queryName: string, validatedInput: unknown): Promise<void>;
  /**
   * Installs the channel-routed command map produced once the runtime is wired to the channel.
   *
   * Load bodies use this map (not the raw local one) so a command implemented only on a peer — e.g. a
   * server-only `extractDocgen` invoked from the manager's `docgen` load — is requested remotely
   * instead of throwing `OpenServiceUnimplementedOperationError` locally. Command names not in
   * `implementedCommandNames` are treated as remote and routed through this map even inside the
   * stale-write-gated reactive load path (remote calls carry no local `setState` to gate).
   */
  attachChannelCommands(
    commands: Record<string, (input: unknown) => Promise<unknown>>,
    implementedCommandNames: ReadonlySet<string>
  ): void;
};

/**
 * Resolves which serialized static-state file should back a query input.
 *
 * The returned value is a logical slash-separated store key scoped under the service id, not a raw
 * filesystem path.
 */
function normalizeStaticStoragePath(serviceId: ServiceId, name: string, rawPath: string): string {
  const segments = rawPath
    .replaceAll('\\', '/')
    .split('/')
    .filter((segment) => segment.length > 0 && segment !== '.');

  // Keep static snapshot keys relative so server-side writers can always anchor them under the
  // build output, regardless of whether authors used '/', './', or Windows-style separators.
  if (segments.length === 0 || segments.some((segment) => segment === '..')) {
    throw new OpenServiceInvalidStaticPathError({ serviceId, name, path: rawPath });
  }

  return segments.join('/');
}

export function resolveStaticPath(
  serviceId: ServiceId,
  name: string,
  queryDef: { staticPath: (input: unknown) => string },
  input: unknown
): string {
  const rawPath = queryDef.staticPath(input);
  const relativePath = normalizeStaticStoragePath(serviceId, name, rawPath);

  // Scope every snapshot under the service id so two services cannot collide on disk.
  return `${serviceId}/${relativePath}`;
}

/**
 * Creates the writable `self` object that backs every runtime ctx for one service instance.
 *
 * State is a deep reactive proxy: mutations applied to `state` notify only the fine-grained signals
 * for the fields that actually changed. Writes are wrapped in a batch so one command only notifies
 * subscribers after the full mutation completes.
 */
function createCommandSelf<TState>(state: TState): CommandSelf<TState> {
  return {
    get state() {
      return state;
    },
    setState(mutate) {
      batch(() => {
        mutate(state);
      });
    },
    queries: {},
    commands: {},
  };
}

/**
 * Builds the runtime command map from the declarative command definitions.
 *
 * Each runtime command validates raw caller input, invokes the handler with parsed values, and
 * validates the resolved output before returning it to the caller.
 */
function buildCommands<TState>(
  serviceId: ServiceId,
  commands: Commands<TState>,
  createCommandCtx: () => CommandCtx<TState>
): Command {
  return Object.fromEntries(
    Object.entries(commands).map(([name, def]) => {
      return [
        name,
        async (input: unknown) => {
          if (!def.handler) {
            throw new OpenServiceUnimplementedOperationError({
              kind: 'command',
              serviceId,
              name,
            });
          }

          const validatedInput = await validateSchema(def.input, input, {
            kind: 'command',
            serviceId,
            name,
            phase: 'input',
          });
          const output = await def.handler(validatedInput, createCommandCtx());

          return validateSchema(def.output, output, {
            kind: 'command',
            serviceId,
            name,
            phase: 'output',
          });
        },
      ];
    })
  );
}

/**
 * When a browser static loader is active, queries with `staticPath` fetch prebuilt JSON instead of
 * running their authored `load` hook (which typically invokes server-only commands).
 */
function buildQueryDefinitionsWithStaticLoader<TState>(
  serviceId: ServiceId,
  queries: Record<string, RuntimeQueryDefinition<TState>>,
  staticLoader: StaticLoader,
  setState: CommandSelf<TState>['setState']
): Map<string, RuntimeQueryDefinition<TState>> {
  return new Map(
    Object.entries(queries).map(([name, queryDef]) => {
      if (!queryDef.staticPath) {
        return [name, queryDef] as [string, RuntimeQueryDefinition<TState>];
      }

      const { staticPath } = queryDef;

      return [
        name,
        {
          ...queryDef,
          load: async (input: unknown) => {
            const logicalPath = resolveStaticPath(serviceId, name, { staticPath }, input);
            const snapshot = await staticLoader(logicalPath, {
              serviceId,
              queryName: name,
              input,
            });

            // Unlike reactive loads (which gate writes through `buildGatedCommands` so a superseded
            // run cannot clobber a newer one), this write is ungated. Static snapshots are immutable
            // and keyed per input via `staticPath(input)`, so re-running the same input produces
            // identical data and `preserveMissingKeys: true` never erases a sibling input's state —
            // there is no stale-write race to guard against.
            setState((state) => {
              applyStatePatch(state as Record<string, unknown>, snapshot, {
                preserveMissingKeys: true,
              });
            });
          },
        },
      ] as [string, RuntimeQueryDefinition<TState>];
    })
  );
}

/**
 * Creates the full runtime backing for a service definition.
 *
 * Callers must supply the registry API that query and command contexts should expose.
 */
export function createServiceRuntime<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  def: ServiceDefinition<TState, TQueries, TCommands>,
  runtimeOptions: {
    registryApi: ServiceRegistryApi;
    staticLoader?: StaticLoader;
  },
  initialState: TState = def.initialState
): ServiceRuntime<TState, TQueries, TCommands> {
  // `initialState` is the plain backing object that the deep-signal proxy writes through to; it
  // stays in sync with every mutation and is the source for serialization snapshots. The runtime
  // mutates it in place, so callers that share an object (e.g. a definition's `initialState`) must
  // pass their own copy — `registerService` and the static build each do.
  const rawState = initialState;
  // The deep reactive proxy is the single source of truth that query computations track, at
  // per-field granularity.
  const state = deepSignal(rawState as object) as TState;
  const getStateSnapshot = (): TState => structuredClone(rawState);
  const commandSelf = createCommandSelf(state);
  const { registryApi, staticLoader } = runtimeOptions;
  const createCommandCtx = (): CommandCtx<TState> => ({
    self: commandSelf,
    getService: registryApi.getService,
  });

  const commands = buildCommands(def.id, def.commands, createCommandCtx) as ServiceInstance<
    TState,
    TQueries,
    TCommands
  >['commands'];
  commandSelf.commands = commands as CommandSelf<TState>['commands'];

  // The command map load bodies should call. Defaults to the raw local map (used by the static build
  // and before the channel is wired); `attachChannelCommands` swaps in the channel-routed map so
  // loads can invoke peer-implemented commands remotely. `remoteCommandNames` is the set of commands
  // with no local handler in this runtime, which the gated reactive-load path routes through the
  // channel map directly (they have no local `setState` to gate).
  let loadCommands = commands as CommandSelf<TState>['commands'];
  const remoteCommandNames = new Set<string>();

  const queryDefinitions = staticLoader
    ? buildQueryDefinitionsWithStaticLoader(
        def.id,
        def.queries as Record<string, RuntimeQueryDefinition<TState>>,
        staticLoader,
        commandSelf.setState
      )
    : new Map<string, RuntimeQueryDefinition<TState>>(
        Object.entries(def.queries) as [string, RuntimeQueryDefinition<TState>][]
      );
  const defaultQueries: Record<string, Query<unknown, unknown>> = {};
  // Populated after the default queries exist (their wrappers reference the default `getState` /
  // `loaded` / `subscribe`). See `buildReactiveLoadQueries`.
  const reactiveLoadQueries: Record<string, Query<unknown, unknown>> = {};

  // Gated commands for reactive subscription loads: a stale run's writes are dropped once a newer
  // run has started (`isCurrent()` returns false), so superseded loads cannot clobber fresh state.
  const buildGatedCommands = (isCurrent: () => boolean): CommandSelf<TState>['commands'] => {
    const gatedSelf: CommandSelf<TState> = {
      get state() {
        return state;
      },
      setState(mutate) {
        if (!isCurrent()) {
          return;
        }
        batch(() => {
          mutate(state);
        });
      },
      queries: defaultQueries,
      commands: {},
    };
    const gated = buildCommands(def.id, def.commands, () => ({
      self: gatedSelf,
      getService: registryApi.getService,
    }));
    gatedSelf.commands = gated as CommandSelf<TState>['commands'];

    // Route remote commands through the channel map (so a reactive load can invoke a peer command);
    // keep the gated local wrapper for locally-handled commands so stale-write protection holds.
    if (remoteCommandNames.size === 0) {
      return gated as CommandSelf<TState>['commands'];
    }
    const routed = Object.fromEntries(
      Object.keys(def.commands).map((name) => [
        name,
        remoteCommandNames.has(name)
          ? (loadCommands as Record<string, unknown>)[name]
          : (gated as Record<string, unknown>)[name],
      ])
    );
    return routed as CommandSelf<TState>['commands'];
  };

  const refs: QueryRuntimeRefs<TState> = {
    serviceId: def.id,
    commandSelf,
    state,
    registryApi,
    queryDefinitions,
    defaultQueries,
    reactiveLoadQueries,
    getLoadCommands: () => loadCommands,
    buildGatedCommands,
  };

  // Build queries after commands so handler/load ctx surfaces resolve the same command map.
  const builtQueries = buildQueries(refs);
  for (const [name, query] of Object.entries(builtQueries)) {
    defaultQueries[name] = query;
  }
  // Reactive-load wrappers reference the default queries, so build them once those exist.
  for (const [name, query] of Object.entries(buildReactiveLoadQueries(refs))) {
    reactiveLoadQueries[name] = query;
  }
  commandSelf.queries = defaultQueries;

  const queries = defaultQueries as ServiceInstance<TState, TQueries, TCommands>['queries'];
  const queryCtxSelf: QuerySelf<TState> = {
    get state() {
      return state;
    },
    queries: defaultQueries,
  };
  const queryCtx: QueryCtx<TState> = { self: queryCtxSelf, getService: registryApi.getService };
  const loadCtxForStatic: LoadCtx<TState> = {
    self: {
      get state() {
        return state;
      },
      queries: defaultQueries,
      commands: commands as LoadSelf<TState>['commands'],
    },
    getService: registryApi.getService,
  };

  /**
   * Runs one query's `load` body against this runtime instance, drained to completion.
   *
   * Used by the static build pipeline to populate state for a single input without holding the
   * load in the in-flight registry afterwards.
   */
  const runLoadOnce = async (queryName: string, validatedInput: unknown): Promise<void> => {
    const queryDef = queryDefinitions.get(queryName);

    if (!queryDef || !queryDef.load) {
      return;
    }

    const loadKey = makeLoadKey(def.id, queryName, validatedInput);
    const ancestorChain = new Set<string>([loadKey]) as ReadonlySet<string>;

    // Register this runtime's root load without joining an unrelated in-flight entry from another
    // runtime instance (e.g. the live singleton during parallel staticInputs resolution).
    const previous = inFlightLoads.get(loadKey);
    const promise = Promise.resolve()
      .then(() => runLoadBody(refs, queryName, queryDef, validatedInput, ancestorChain))
      .finally(() => {
        if (inFlightLoads.get(loadKey) === promise) {
          if (previous) {
            inFlightLoads.set(loadKey, previous);
          } else {
            inFlightLoads.delete(loadKey);
          }
        }
      });

    inFlightLoads.set(loadKey, promise);
    await promise;
  };

  const attachChannelCommands = (
    channelCommands: Record<string, (input: unknown) => Promise<unknown>>,
    implementedCommandNames: ReadonlySet<string>
  ): void => {
    loadCommands = channelCommands as CommandSelf<TState>['commands'];
    remoteCommandNames.clear();
    for (const name of Object.keys(def.commands)) {
      if (!implementedCommandNames.has(name)) {
        remoteCommandNames.add(name);
      }
    }
  };

  return {
    getStateSnapshot,
    commandSelf,
    queryCtx,
    loadCtxForStatic,
    commands,
    queries,
    runLoadOnce,
    attachChannelCommands,
  };
}

/** Re-export so external modules can address the in-flight load registry for tests if needed. */
export const __internalInFlightLoads = inFlightLoads;

/** Type referenced from the registry surface for cross-service callers. */
export type { RuntimeService };

import { describe, expect, it } from 'vitest';

import { applyStatePatch } from './service-sync.ts';

describe('applyStatePatch', () => {
  it('merges nested objects without deleting sibling keys', () => {
    const target = { entries: { alpha: 'a', beta: 'b' } };
    const source = { entries: { gamma: 'c' } };

    applyStatePatch(target as Record<string, unknown>, source as Record<string, unknown>, {
      preserveMissingKeys: true,
    });

    expect(target).toEqual({ entries: { alpha: 'a', beta: 'b', gamma: 'c' } });
  });

  it('replaces primitive values when the source differs', () => {
    const target = { value: 'old' };
    const source = { value: 'new' };

    applyStatePatch(target, source, { preserveMissingKeys: true });

    expect(target).toEqual({ value: 'new' });
  });

  // A JSON object literal would make `__proto__` set the prototype rather than an own key, so the
  // guard would never run. `JSON.parse` produces real own `__proto__`/`constructor`/`prototype`
  // keys, which is exactly the untrusted payload shape that reaches this code from static files and
  // channel snapshots.
  const pollutionSource = () =>
    JSON.parse(
      '{"__proto__":{"polluted":true},"constructor":{"polluted":true},"prototype":{"polluted":true},"safe":"updated"}'
    ) as Record<string, unknown>;

  it('skips prototype-pollution keys when preserving missing keys', () => {
    const target = { safe: 'ok' };

    applyStatePatch(target, pollutionSource(), { preserveMissingKeys: true });

    expect(target).toEqual({ safe: 'updated' });
    expect(({} as Record<string, unknown>).polluted).toBeUndefined();
    expect((Object.getPrototypeOf({}) as Record<string, unknown>).polluted).toBeUndefined();
  });

  it('skips prototype-pollution keys when deleting missing keys', () => {
    const target = { safe: 'ok' };

    applyStatePatch(target, pollutionSource(), { preserveMissingKeys: false });

    expect(target).toEqual({ safe: 'updated' });
    expect(({} as Record<string, unknown>).polluted).toBeUndefined();
    expect((Object.getPrototypeOf({}) as Record<string, unknown>).polluted).toBeUndefined();
  });

  it('deletes nested keys missing from the source snapshot', () => {
    const target = { entries: { alpha: 'a', beta: 'b' }, untouched: true };
    const source = { entries: { alpha: 'updated' } };

    applyStatePatch(target as Record<string, unknown>, source as Record<string, unknown>, {
      preserveMissingKeys: false,
    });

    expect(target).toEqual({ entries: { alpha: 'updated' } });
  });
});

/**
 * Shared sync primitives for the open-service multi-master protocol.
 *
 * Every runtime — server (Node), manager (top window), preview (iframe) — runs a full
 * `ServiceRuntime` and reconciles incoming state with the same two rules — last-write-wins ordering
 * and structural merge — so this module is the single source of truth for all of them. The
 * transport that moves snapshots on and off the channel lives in `service-transport.ts`, which every
 * `registerService` entrypoint drives through these primitives (see `service-transport-leaf.test.ts`
 * and `service-registration-sync.test.ts`).
 *
 * ## 1. `isNewer` — last-write-wins ordering
 *
 * Each synced snapshot carries a `(version, clientId)` stamp. `version` is a logical clock for the
 * state lineage: a runtime bumps it on every local command and adopts the incoming value when it
 * accepts a peer's snapshot. Equal versions mean concurrent writes; the lexicographically greater
 * `clientId` wins so every runtime independently converges on the same snapshot regardless of the
 * order events arrive in.
 *
 * Crucially, an *equal* stamp is **not** newer. That single fact is what makes the protocol
 * echo-safe and relay-safe: a snapshot a runtime already holds (its own broadcast bouncing back,
 * or a hub re-emitting an already-applied patch) fails `isNewer` and is dropped instead of
 * re-applied and re-broadcast, so update storms terminate.
 *
 * The stamp lives in the channel envelope, never inside the user state object. Service authors and
 * consumers never declare it, read it, or subscribe to it — whole-state-per-service LWW is a
 * documented semantic of the protocol, not a field anyone has to think about.
 *
 * ## 2. `applyStatePatch` — structural merge
 *
 * Applies incoming state onto the live state object in place so that deep-signal subscriptions only
 * re-fire for the fields that actually changed. Full peer snapshots delete keys absent from the
 * source so deletions propagate; partial static snapshots preserve missing keys. Arrays are replaced
 * wholesale, primitives are assigned only when changed, and the dangerous
 * `__proto__`/`constructor`/`prototype` keys are skipped on both read and delete so hostile payloads
 * cannot pollute the prototype chain.
 */

/** Per-service last-write-wins stamp carried alongside every synced snapshot. */
export type SyncStamp = {
  /** Logical clock for the state lineage. Bumped on every local command, adopted on accept. */
  version: number;
  /** Id of the runtime that produced this version; the deterministic tiebreak for equal versions. */
  clientId: string;
};

/**
 * Returns whether `incoming` should replace `local` under last-write-wins ordering.
 *
 * Higher `version` always wins. At an equal version (concurrent writes) the lexicographically
 * greater `clientId` wins so every runtime picks the same winner. An equal stamp is **not** newer —
 * that is precisely what makes echoes and relayed re-broadcasts terminate rather than loop.
 */
export function isNewer(incoming: SyncStamp, local: SyncStamp): boolean {
  if (incoming.version !== local.version) {
    return incoming.version > local.version;
  }

  return incoming.clientId > local.clientId;
}

/** Keys never copied from an untrusted payload, to block prototype-pollution. */
const FORBIDDEN_KEYS = new Set<string>(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Applies `source` onto `target` in place while preserving object identity for unchanged branches.
 *
 * Open-service runtimes expose their state through deep-signal proxies. Replacing the whole state
 * object for every incoming snapshot would invalidate all subscriptions, even when only one nested
 * field changed. This helper instead walks both objects and mutates `target` only where values differ:
 *
 * - Recurses into plain objects so nested deep-signal subscriptions stay attached.
 * - Replaces arrays wholesale, matching the sync contract that arrays are values rather than maps.
 * - Assigns primitives only when changed to avoid spurious signal invalidation.
 * - Skips `__proto__`, `constructor`, and `prototype` on both delete and assign paths so untrusted
 *   channel payloads and static files cannot pollute prototypes.
 *
 * The `preserveMissingKeys` mode selects the source contract:
 *
 * - `false` means `source` is a full peer snapshot. Keys missing from `source` are deleted from
 *   `target`, allowing deletions to propagate through cross-peer sync.
 * - `true` means `source` is a partial static snapshot. Keys missing from `source` are left alone so
 *   snapshots for one static query input do not erase state populated by other inputs.
 */
export function applyStatePatch(
  target: Record<string, unknown>,
  source: Record<string, unknown>,
  options: { preserveMissingKeys: boolean }
): void {
  if (!options.preserveMissingKeys) {
    // Remove keys the source no longer carries (deletion propagation).
    for (const key of Object.keys(target)) {
      if (FORBIDDEN_KEYS.has(key)) {
        continue;
      }

      if (!Object.prototype.hasOwnProperty.call(source, key)) {
        delete target[key];
      }
    }
  }

  // Merge or assign keys the source provides.
  for (const key of Object.keys(source)) {
    if (FORBIDDEN_KEYS.has(key)) {
      continue;
    }

    const sourceValue = source[key];
    const tarvalue = target[key];

    if (isPlainObject(sourceValue) && isPlainObject(tarvalue)) {
      applyStatePatch(tarvalue, sourceValue, options);
    } else if (tarvalue !== sourceValue) {
      target[key] = sourceValue;
    }
  }
}

/** In-place mutation of a runtime's live state object, as exposed by `commandSelf.setState`. */
export type StateMutator = (state: Record<string, unknown>) => void;

/**
 * The per-service reconciler shared by every runtime's channel integration.
 *
 * It owns the last-write-wins stamp and exposes the only two stamp transitions the protocol allows:
 * advancing for a locally authored change, and adopting a strictly-newer peer snapshot. Centralizing
 * this here is deliberate — the client and server transports used to each carry their own copy of
 * the merge logic, which is exactly how they could silently drift apart.
 */
export type SnapshotReconciler = {
  /** The current local stamp (read for sync-start-reply / broadcast envelopes). */
  readonly stamp: SyncStamp;
  /**
   * Records a locally authored change: bumps `version` and re-stamps with `clientId`. Call this
   * before broadcasting so the broadcast's own echo is recognized as not-newer and dropped.
   */
  advanceLocal(clientId: string): SyncStamp;
  /**
   * Adopts an incoming snapshot iff it is strictly newer (LWW). Returns whether it was adopted, so
   * relay hubs can re-broadcast only on a real advance.
   */
  tryAdopt(incoming: SyncStamp, state: Record<string, unknown>): boolean;
};

/**
 * Builds a {@link SnapshotReconciler} bound to one runtime's state.
 *
 * @param setState - The runtime's batched in-place mutator (`commandSelf.setState`), adapted to a
 *   plain record. Adopting goes through this rather than the wrapped commands so it never triggers
 *   a re-broadcast.
 * @param initialStamp - Starting stamp, typically `{ version: 0, clientId: <own id> }`.
 */
export function createSnapshotReconciler(options: {
  setState: (mutate: StateMutator) => void;
  initialStamp: SyncStamp;
}): SnapshotReconciler {
  const { setState, initialStamp } = options;
  let localStamp = initialStamp;

  return {
    get stamp(): SyncStamp {
      return localStamp;
    },

    advanceLocal(clientId: string): SyncStamp {
      localStamp = { version: localStamp.version + 1, clientId };
      return localStamp;
    },

    tryAdopt(incoming: SyncStamp, state: Record<string, unknown>): boolean {
      if (!isNewer(incoming, localStamp)) {
        return false;
      }

      localStamp = { version: incoming.version, clientId: incoming.clientId };
      setState((current) => applyStatePatch(current, state, { preserveMissingKeys: false }));

      return true;
    },
  };
}

