      `
    );
  });

  it('shows the full actionable message for invalid command input', async () => {
    const service = registerService(mutableRecordLookupServiceDef);

    await expectValidationMessage(
      () =>
        service.commands.assignRecordField({
          entryId: 'entry-a',
          fieldKey: 'marker',
          fieldValue: 1,
        } as unknown as {
          entryId: string;
          fieldKey: string;
          fieldValue: string;
