  it('shows the full actionable message for invalid command output', async () => {
    const service = registerService(createInvalidCommandOutputServiceDef());

    await expectValidationMessage(
      () => service.commands.runBrokenCommand(undefined),
      dedent`
        Invalid output for command "internal-fixture/invalid-command-output.runBrokenCommand":
        Invalid type: Expected string but received 42
      `
    );
  });

  it('shows the full actionable message for invalid static load input', async () => {
    registerService(createInvalidStaticInputServiceDef());

    await expectValidationMessage(
      () => buildStaticFiles(),
      dedent`
        Invalid input for query "internal-fixture/invalid-static-input.preloadedValue":
        entryId: Invalid key: Expected "entryId" but received undefined
      `
    );
  });

  it('shows nested field paths for validation issues inside arrays and objects', async () => {
    const service = registerService(
      defineService({
        id: 'internal-fixture/nested-query-output',
        initialState: {} as Record<string, never>,
        queries: {
          brokenTree: {
            input: v.undefined(),
            output: v.object({
              items: v.array(
                v.object({
                  name: v.string(),
                })
              ),
            }),
            handler: () => ({
              items: [{ name: 1 as unknown as string }] as Array<{ name: string }>,
            }),
          },
        },
        commands: {},
      })
    );

    await expectValidationMessage(
      () => service.queries.brokenTree.get(undefined),
      dedent`
        Invalid output for query "internal-fixture/nested-query-output.brokenTree":
        items[0].name: Invalid type: Expected string but received 1
      `
    );
  });

  it('wraps zod schema issues in the same actionable validation error shape', async () => {
    const service = registerService(
      defineService({
        id: 'internal-fixture/zod-query-input',
        initialState: {} as Record<string, never>,
        queries: {
          greeting: {
            input: z.object({
              name: z.string().min(2, 'Name must be at least 2 characters'),
            }),
            output: z.string(),
            handler: ({ name }) => `Hello ${name}`,
          },
        },
        commands: {},
      })
    );

    await expectValidationMessage(
      () => service.queries.greeting.get({ name: 'x' }),
      dedent`
        Invalid input for query "internal-fixture/zod-query-input.greeting":
        name: Name must be at least 2 characters
      `
    );
  });

  it('accepts unexpected query input fields when the schema allows them', () => {
    const service = registerService(mutableRecordLookupServiceDef);

    expect(
      service.queries.recordFields.get({
        entryId: 'entry-a',
        unexpected: 'extra',
      } as unknown as { entryId: string })
    ).toBeNull();
  });

  it('accepts unexpected command input fields when the schema allows them', async () => {
    const service = registerService(mutableRecordLookupServiceDef);

    await expect(
      service.commands.assignRecordField({
        entryId: 'entry-a',
        fieldKey: 'marker',
        fieldValue: 'match',
        unexpected: 'extra',
      } as unknown as {
        entryId: string;
        fieldKey: string;
        fieldValue: string;
      })
    ).resolves.toBeUndefined();

    expect(service.queries.recordFields.get({ entryId: 'entry-a' })).toEqual({
      marker: 'match',
    });
  });

  it('stores optional description metadata on services, queries, and commands', () => {
    expect(mutableRecordLookupServiceDef.description).toBe(
      'Provides a mutable record lookup keyed by entry id.'
    );
    expect(mutableRecordLookupServiceDef.queries.recordFields.description).toBe(
      'Returns all stored fields for one entry, or null when absent.'
    );
    expect(mutableRecordLookupServiceDef.commands.assignRecordField.description).toBe(
      'Writes one field value onto the selected entry.'
    );
  });
});

import type { StandardSchemaV1 } from '@standard-schema/spec';

import { OpenServiceAsyncSchemaError, OpenServiceValidationError } from '../../server-errors.ts';
import type { AnySchema } from './types.ts';
import type { ValidationMeta } from './errors.ts';

/**
 * Re-throws asynchronous subscription failures on the microtask queue so they are not silently
 * swallowed by promise chains started from reactive listeners.
 */
export function rethrowAsync(error: unknown): void {
  queueMicrotask(() => {
    throw error;
  });
}

/**
 * Validates a value with a Standard Schema and returns the parsed output value.
 *
 * Any schema issues are wrapped in `OpenServiceValidationError`, which standardizes the operation
 * metadata while preserving the schema's own expectation text for the actionable details.
 */
export async function validateSchema<TSchema extends AnySchema>(
  schema: TSchema,
  value: unknown,
  meta: Omit<ValidationMeta, 'issues'>
): Promise<StandardSchemaV1.InferOutput<TSchema>> {
  const validationResult = await schema['~standard'].validate(value);

  if (validationResult.issues) {
    throw new OpenServiceValidationError({ ...meta, issues: validationResult.issues });
  }

  return validationResult.value;
}

/**
 * Synchronous variant of `validateSchema` used on the sync query call path.
 *
 * Query input and output schemas must produce sync validation results so the public `query(input)`
 * function can return a value immediately. If a schema accidentally returns a Promise, the runtime
 * surfaces a dedicated error instead of silently switching to async behavior.
 */
export function validateSchemaSync<TSchema extends AnySchema>(
  schema: TSchema,
  value: unknown,
  meta: Omit<ValidationMeta, 'issues'>
): StandardSchemaV1.InferOutput<TSchema> {
  const validationResult = schema['~standard'].validate(value);

  if (validationResult instanceof Promise) {
    throw new OpenServiceAsyncSchemaError({
      kind: meta.kind,
      serviceId: meta.serviceId,
      name: meta.name,
      phase: meta.phase,
    });
  }

  if (validationResult.issues) {
    throw new OpenServiceValidationError({ ...meta, issues: validationResult.issues });
  }

  return validationResult.value;
}

import type { StrictArgTypes } from 'storybook/internal/types';

import * as v from 'valibot';

import { defineService } from 'storybook/open-service';
import type { ServiceInstanceOf } from '../../types.ts';
import type { DocgenPayload } from './types.ts';
import { docgenQueryStaticPath } from './paths.ts';

const docgenInputSchema = v.object({ id: v.string() });
// Typed as `StrictArgTypes` (a static Storybook construct) but validated loosely: spelling out the
// full recursive valibot shape is deferred, so this only checks "is a plain object" at runtime
// while keeping the payload's `argTypes` typed for consumers.
const argTypesSchema = v.custom<StrictArgTypes>(
  (value) => typeof value === 'object' && value !== null && !Array.isArray(value)
);

type DocgenServiceState = {
  /** Extracted docgen keyed by component id. Populated by the `extractDocgen` command. */
  components: Record<string, DocgenPayload>;
};

const docgenErrorSchema = v.object({
  name: v.string(),
  message: v.string(),
});

const docgenJsDocTagsSchema = v.record(v.string(), v.array(v.string()));

/** Shared docgen fields on top-level component docgen entries. */
const docgenComponentFields = {
  name: v.string(),
  path: v.string(),
  description: v.optional(v.string()),
  summary: v.optional(v.string()),
  jsDocTags: docgenJsDocTagsSchema,
  argTypes: v.optional(argTypesSchema),
  error: v.optional(docgenErrorSchema),
};

/** Shared docgen fields on subcomponent docgen entries (includes per-subcomponent import). */
const docgenSubcomponentFields = {
  ...docgenComponentFields,
  import: v.optional(v.string()),
};

/**
 * Subcomponent docgen schema.
 *
 * Uses {@link v.looseObject} so provider-specific docgen engine output (for example
 * `reactComponentMeta`) validates without listing every framework integration field in core.
 */
const docgenSubcomponentSchema = v.looseObject(docgenSubcomponentFields);

/**
 * Top-level component docgen payload schema.
 *
 * Uses {@link v.looseObject} for the same reason as {@link docgenSubcomponentSchema}: the open
 * service owns the portable manifest contract while renderers attach engine-specific keys.
 */
const docgenPayloadSchema = v.looseObject({
  id: v.string(),
  ...docgenComponentFields,
  subcomponents: v.optional(v.record(v.string(), docgenSubcomponentSchema)),
});

const docgenOutputSchema = v.optional(docgenPayloadSchema);

/**
 * Definition for the `core/docgen` open service.
 *
 * The service carries only provider-extracted docgen (component name, description, props, JSDoc
 * tags, and the renderer-converted argTypes). Story/meta/project custom argTypes are NOT stored
 * here — consumers layer those in from their own sources (the docs blocks resolve the prepared
 * meta/story locally; the manager Controls panel reads them from the `STORY_PREPARED` channel).
 *
 * The query is a thin synchronous read of `state.components[id]` — it returns undefined when
 * nothing has been extracted yet rather than throwing, matching the open-service convention for
 * sync reads. The real work — story index lookup, provider invocation, error handling — lives in
 * the `extractDocgen` command, whose body is supplied at registration time because it needs to
 * close over the server-only story index and the composed `experimental_docgenProvider` chain.
 * The query's `load` hook calls `extractDocgen`, so `docgen.loaded()` is the awaitable form and
 * surfaces extraction errors. `docgenForAllComponents` delegates to the `extractAllDocgen`
 * command, whose handler is supplied at registration because it needs the story index.
 */
export const docgenServiceDef = defineService({
  id: 'core/docgen',
  internal: true,
  description:
    'Component documentation (name, description, props, JSDoc tags) keyed by component id.',
  initialState: { components: {} } as DocgenServiceState,
  queries: {
    docgen: {
      description: 'Returns the docgen payload for one component id, or undefined when not loaded.',
      input: docgenInputSchema,
      output: docgenOutputSchema,
      handler: (input, ctx) => ctx.self.state.components[input.id],
      load: async (input, ctx) => {
        await ctx.self.commands.extractDocgen(input);
      },
      staticPath: (input) => docgenQueryStaticPath(input.id),
    },
    docgenForAllComponents: {
      description: 'Returns docgen payloads for every component in the story index.',
      input: v.void(),
      output: v.record(v.string(), docgenPayloadSchema),
      handler: (_input, ctx) => ctx.self.state.components,
      load: async (_input, ctx) => {
        await ctx.self.commands.extractAllDocgen(undefined);
      },
    },
  },
  commands: {
    extractDocgen: {
      description:
        'Resolves the story entry for a component id, runs the registered provider chain, writes the result into state, and returns it (or undefined when no provider produced docgen).',
      input: docgenInputSchema,
      output: docgenOutputSchema,
      // Handler is supplied at registration time so it can close over the story index and the
      // composed experimental_docgenProvider chain.
    },
    extractAllDocgen: {
      description:
        'Extracts docgen for every component id in the story index by invoking `extractDocgen` for each.',
      input: v.undefined(),
      output: v.void(),
      // Handler is supplied at registration time so it can close over the story index.
    },
  },
});

export type DocgenService = ServiceInstanceOf<typeof docgenServiceDef>;

