      reverseIndex,
      graph,
      storyFiles: new Set(),
    });

    await patcher.patch({ kind: 'unlink', path: story });

    expect(reverseIndex.asMap().has(story)).toBe(false);
    expect(reverseIndex.asMap().has(dep)).toBe(false);
    expect(graph.has(story)).toBe(false);
  });

  it('walkStory invalidates story cache so stale deps are not re-added after re-walk', async () => {
    // Regression: when a dep file changes and its story is re-walked, the cache held a
    // stale entry for the story (from the cold-start build). Without cache.invalidate(storyRoot)
    // in walkStory, walkFromStory would read the stale cached result and silently re-add the
    // removed dep back into the graph / reverseIndex.
    const story = '/repo/src/A.stories.tsx';
    const dep = '/repo/src/dep.ts';
    const extra = '/repo/src/extra.ts';
    const dep2 = '/repo/src/dep2.ts';

    const world: PatcherWorld = {
      edges: new Map([
        [story, [{ specifier: './dep.ts', kind: 'static', importedNames: null }]],
        [dep, [{ specifier: './extra.ts', kind: 'static', importedNames: null }]],
        [extra, []],
      ]),
      resolutions: new Map([
        [`${story}::./dep.ts`, dep],
        [`${dep}::./extra.ts`, extra],
      ]),
    };

    const { patcher, reverseIndex } = buildPatcher({
      world,
      storyFiles: new Set([story]),
    });

    // Seed the cache: walk the story once to populate cache entries for story and dep.
    await patcher.patch({ kind: 'add', path: story });
    expect(reverseIndex.lookup(dep).get(story)).toBe(1);

    // Mutate world: story no longer imports dep.
    world.edges.set(story, []);

    // Mutate world: dep gains a new import so the setsEqual check does not short-circuit.
    world.edges.set(dep, [
      { specifier: './extra.ts', kind: 'static', importedNames: null },
      { specifier: './dep2.ts', kind: 'static', importedNames: null },
    ]);
    world.resolutions.set(`${dep}::./dep2.ts`, dep2);

    // A change on dep triggers re-walk of every story that depends on it (= our story).
    await patcher.patch({ kind: 'change', path: dep });

    // story cache was invalidated before re-walk → story resolves to [] → dep pruned.
    expect(reverseIndex.lookup(dep).size).toBe(0);
    expect(reverseIndex.lookup(story).get(story)).toBe(0);
  });

  it('parses the story root exactly once when the graph entry is absent (no diff-check path)', async () => {
    // graph is empty so graph.get(path) === undefined → skip the resolveOnce diff-check
    // → walkStory calls resolveOnce once → parseOnce called exactly once.
    const story = '/repo/src/A.stories.tsx';
    const initialIndex = new ReverseIndexImpl();
    initialIndex.record(story, story, 0);
    const world: PatcherWorld = {
      edges: new Map([[story, []]]),
      resolutions: new Map(),
    };
    const { patcher, parseSpy } = buildPatcher({
      world,
      reverseIndex: initialIndex,
      storyFiles: new Set([story]),
    });

    await patcher.patch({ kind: 'change', path: story });

    const calls = parseSpy.mock.calls.filter((c) => c[0].filePath === story);
    expect(calls.length).toBe(1);
  });

  it('unlink of a dep clears the dep from the graph and from the story reverse-index, not just from the index edges', async () => {
    // Models the stale-cache regression: story → dep is seeded into graph + reverseIndex at
    // cold-start. Without importer invalidation on unlink, walkFromStory re-uses the cached
    // resolveCache entry for `story` (which still lists `dep`), silently re-adding dep to
    // the graph and leaving reverseIndex.lookup(dep) non-empty.
    const story = '/repo/src/A.stories.tsx';
    const dep = '/repo/src/dep.ts';

    const initialIndex = new ReverseIndexImpl();
    initialIndex.record(story, story, 0);
    initialIndex.record(dep, story, 1);
    const initialGraph: DependencyGraph = new Map([
      [story, new Set([dep])],
      [dep, new Set()],
    ]);

    // After unlink, the story no longer imports dep.
    const world: PatcherWorld = {
      edges: new Map([[story, []]]),
      resolutions: new Map(),
    };
    const { patcher, reverseIndex, graph } = buildPatcher({
      world,
      reverseIndex: initialIndex,
      graph: initialGraph,
      storyFiles: new Set([story]),
    });

    await patcher.patch({ kind: 'unlink', path: dep });

    expect(reverseIndex.lookup(dep).size).toBe(0);
    expect(graph.has(dep)).toBe(false);
    // The story itself still exists at depth 0; dep is no longer reachable from it.
    expect(reverseIndex.lookup(story).get(story)).toBe(0);
  });
});

import { normalize } from 'pathe';

import { logger as defaultLogger } from 'storybook/internal/node-logger';

import type { FileChangeEvent } from '../adapters/types.ts';
import type { ParserRegistry } from '../parser-registry/parser-registry.ts';
import { ParseResolveCache } from './parse-resolve-cache.ts';
import type { ReverseIndexImpl } from './reverse-index.ts';
import type { ChangeDetectionResolverFactory } from './resolver-factory.ts';
import type { DependencyGraph } from './types.ts';
import { walkFromStory } from './walk-from-story.ts';

function setsEqual(a: Set<string>, b: Set<string>): boolean {
  if (a.size !== b.size) {
    return false;
  }
  for (const item of a) {
    if (!b.has(item)) {
      return false;
    }
  }
  return true;
}

interface PatcherLogger {
  debug: (message: string) => void;
  warn: (message: string) => void;
}

interface PatcherOptions {
  reverseIndex: ReverseIndexImpl;
  graph: DependencyGraph;
  registry: ParserRegistry;
  resolver: ChangeDetectionResolverFactory;
  workspaceRoots: Set<string>;
  projectRoot: string;
  logger?: PatcherLogger;
  /** Set-style predicate: returns true if the path is a story-root file. */
  isStoryFile: (path: string) => boolean;
  /**
   * Optional shared cache. When the patcher and {@link DependencyGraphBuilder} share the
   * same instance, post-build incremental walks reuse parse + resolve results from the
   * cold-start build. The patcher invalidates `path` on every `change`/`unlink` event
   * before reading.
   */
  cache?: ParseResolveCache;
}

/**
 * Applies a single {@link FileChangeEvent} to the live reverse index + graph.
 *
 * `patch()` mutates `graph` and `reverseIndex` across multiple `await` points, so the caller
 * MUST serialise concurrent calls; {@link ChangeDetectionService} chains them through
 * `patchQueue`.
 *
 * Known limitation: files that are unresolved at cold-start (resolver returns null so they
 * never enter the graph) are not automatically reconnected when they later appear on disk.
 * A full rebuild is required to pick them up.
 */
export class IncrementalPatcher {
  private readonly reverseIndex: ReverseIndexImpl;
  private readonly graph: DependencyGraph;
  private readonly registry: ParserRegistry;
  private readonly logger: PatcherLogger;
  private readonly isStoryFile: (path: string) => boolean;
  private readonly cache: ParseResolveCache;

  constructor(opts: PatcherOptions) {
    this.reverseIndex = opts.reverseIndex;
    this.graph = opts.graph;
    this.registry = opts.registry;
    this.logger = opts.logger ?? defaultLogger;
    this.isStoryFile = opts.isStoryFile;
    this.cache =
      opts.cache ??
      new ParseResolveCache({
        registry: opts.registry,
        resolver: opts.resolver,
        workspaceRoots: opts.workspaceRoots,
        projectRoot: opts.projectRoot,
        logger: this.logger,
      });
  }

  async patch(event: FileChangeEvent): Promise<void> {
    const path = normalize(event.path);
    // File contents may have changed (or the file is gone); drop any stale cached
    // parse/resolve data before any read.
    this.cache.invalidate(path);

    if (event.kind === 'add') {
      if (this.isStoryFile(path)) {
        await this.walkStory(path);
      }
      // Non-story add: the documented limitation says we don't recover unresolved deps.
      return;
    }

    if (event.kind === 'unlink') {
      const dependentsSet = new Set(this.reverseIndex.lookup(path).keys());
      this.graph.delete(path);
      this.reverseIndex.removeStory(path); // always call — no-op for non-stories
      // Re-walk every dependent story so transitive deps reachable only through `path`
      // are pruned.
      const storiesToWalk: string[] = [];
      for (const story of dependentsSet) {
        if (story === path || !this.isStoryFile(story)) {
          continue;
        }
        this.reverseIndex.removeStory(story);
        storiesToWalk.push(story);
      }
      await Promise.all(storiesToWalk.map((story) => this.walkStory(story)));
      return;
    }

    // 'change' on an existing file: re-walk every story that depends on this file
    // (plus the file itself if it's a story). The walk re-resolves dependencies via
    // the cache (already invalidated above) and rebuilds the relevant slice of the
    // graph and reverse-index.
    const affectedStories = new Set(this.reverseIndex.lookup(path).keys());
    if (this.isStoryFile(path)) {
      affectedStories.add(path);
    }

    // Skip re-walk when the file's direct dependency set is unchanged (e.g. on a
    // comment-only or logic-only edit). The graph and reverse-index remain accurate.
    const oldDeps = this.graph.get(path);
    if (oldDeps !== undefined) {
      const newDeps = await this.cache.resolveOnce(path);
      if (setsEqual(oldDeps, newDeps)) {
        return;
      }
    }

    const storiesToWalk: string[] = [];
    for (const story of affectedStories) {
      if (!this.isStoryFile(story)) {
        continue;
      }
      this.reverseIndex.removeStory(story);
      storiesToWalk.push(story);
    }
    await Promise.all(storiesToWalk.map((story) => this.walkStory(story)));
  }

  private walkStory(storyRoot: string): Promise<void> {
    this.cache.invalidate(storyRoot);
    return walkFromStory({
      storyRoot,
      registry: this.registry,
      cache: this.cache,
      reverseIndex: this.reverseIndex,
      recordEdges: (file, deps) => {
        this.graph.set(file, deps);
      },
    });
  }
}

// Tests for ParseResolveCache focusing on the multi-hop barrel chain-following logic.
// The registry parser and parseBarrelInfo are stubbed; readFile returns empty strings so
// the stubs own all edge/barrel decisions.  No oxc binary is needed.
import { afterEach, describe, expect, it, vi } from 'vitest';

import { readFile } from 'node:fs/promises';

import * as oxcParser from 'storybook/internal/oxc-parser';

import { ParserRegistry } from '../parser-registry/parser-registry.ts';
import type { ImportEdge, ImportParser } from '../parser-registry/types.ts';
import { ParseResolveCache } from './parse-resolve-cache.ts';
import type { ChangeDetectionResolverFactory } from './resolver-factory.ts';

vi.mock('node:fs/promises', { spy: true });
vi.mock('storybook/internal/oxc-parser', { spy: true });

type Resolutions = Map<string, string | null>;
type BarrelInfoMap = Map<string, oxcParser.BarrelInfo>;
type EdgesMap = Map<string, ImportEdge[]>;

function makeRegistry(edges: EdgesMap): ParserRegistry {
  const parser: ImportParser = {
    extensions: ['.ts', '.tsx', '.js', '.jsx'],
    parse: vi.fn(async ({ filePath }) => edges.get(filePath) ?? []),
  };
  return new ParserRegistry({ defaultParsers: [parser], pluginParsers: [] });
}

function makeResolver(resolutions: Resolutions): ChangeDetectionResolverFactory {
  return {
    resolve: vi.fn(async (from: string, specifier: string) => {
      const key = `${from}::${specifier}`;
      return resolutions.has(key) ? resolutions.get(key)! : null;
    }),
  } as unknown as ChangeDetectionResolverFactory;
}

const logger = { debug: vi.fn(), warn: vi.fn() };

function makeCache(opts: {
  edges: EdgesMap;
  resolutions: Resolutions;
  barrelInfos: BarrelInfoMap;
  projectRoot?: string;
  workspaceRoots?: Set<string>;
}): ParseResolveCache {
  vi.mocked(readFile).mockImplementation(async () => '');
  vi.mocked(oxcParser.parseBarrelInfo).mockImplementation(async (filePath) => {
    return opts.barrelInfos.get(filePath) ?? { named: new Map(), wildcards: [] };
  });
  return new ParseResolveCache({
    registry: makeRegistry(opts.edges),
    resolver: makeResolver(opts.resolutions),
    workspaceRoots: opts.workspaceRoots ?? new Set(),
    projectRoot: opts.projectRoot ?? '/repo',
    logger,
  });
}

describe('ParseResolveCache — multi-hop barrel following', () => {
  afterEach(() => {
    vi.clearAllMocks();
  });

  it('resolves a name through named → wildcard → named chain to the leaf source file', async () => {
    // Barrel A:  export { Link, LinkBase } from './Link'         ← named
    // Barrel B:  export * from './components/Link'              ← wildcard
    // Barrel C:  export { Link } from './Link.tsx'              ← named
    // Link.tsx:  defines Link (no re-exports)
    const barrelA = '/repo/lib/ui/index.ts';
    const barrelB = '/repo/lib/ui/Link/index.ts';
    const barrelC = '/repo/lib/ui/Link/components/Link/index.ts';
    const linkTsx = '/repo/lib/ui/Link/components/Link/Link.tsx';
    const story = '/repo/story.tsx';

    const cache = makeCache({
      edges: new Map([
        [story, [{ specifier: '@ui', importedNames: new Set(['Link']), kind: 'static' }]],
      ]),
      resolutions: new Map([
        [`${story}::@ui`, barrelA],
        [`${barrelA}::./Link`, barrelB],
        [`${barrelB}::./components/Link`, barrelC],
        [`${barrelC}::./Link.tsx`, linkTsx],
      ]),
      barrelInfos: new Map([
        [
          barrelA,
          {
            named: new Map([
              ['Link', { specifier: './Link', importedName: 'Link' }],
              ['LinkBase', { specifier: './Link', importedName: 'LinkBase' }],
            ]),
            wildcards: [],
          },
        ],
        [barrelB, { named: new Map(), wildcards: ['./components/Link'] }],
        [
          barrelC,
          {
            named: new Map([['Link', { specifier: './Link.tsx', importedName: 'Link' }]]),
            wildcards: [],
          },
        ],
        [linkTsx, { named: new Map(), wildcards: [] }],
      ]),
    });

    const deps = await cache.resolveOnce(story);

    // All traversed barrels are in deps so structural re-export changes at any hop
    // invalidate this importer via the reverse index.
    expect(deps).toEqual(new Set([linkTsx, barrelA, barrelB, barrelC]));
    expect(deps.has(barrelA)).toBe(true);
    expect(deps.has(barrelB)).toBe(true);
    expect(deps.has(barrelC)).toBe(true);
  });

  it('does not include LinkBase.tsx when story only imports Link', async () => {
    // Both symbols live in the same intermediate barrel B. Only Link is requested.
    const barrelA = '/repo/lib/ui/index.ts';
    const barrelB = '/repo/lib/ui/Link/index.ts';
    const linkTsx = '/repo/lib/ui/Link/Link.tsx';
    const linkBaseTsx = '/repo/lib/ui/Link/LinkBase.tsx';
    const story = '/repo/story.tsx';

    const cache = makeCache({
      edges: new Map([
        [story, [{ specifier: '@ui', importedNames: new Set(['Link']), kind: 'static' }]],
      ]),
      resolutions: new Map([
        [`${story}::@ui`, barrelA],
        [`${barrelA}::./Link`, barrelB],
        [`${barrelB}::./Link.tsx`, linkTsx],
        [`${barrelB}::./LinkBase.tsx`, linkBaseTsx],
      ]),
      barrelInfos: new Map([
        [
          barrelA,
          {
            named: new Map([
              ['Link', { specifier: './Link', importedName: 'Link' }],
              ['LinkBase', { specifier: './Link', importedName: 'LinkBase' }],
            ]),
            wildcards: [],
          },
        ],
        [
          barrelB,
          {
            named: new Map([
              ['Link', { specifier: './Link.tsx', importedName: 'Link' }],
              ['LinkBase', { specifier: './LinkBase.tsx', importedName: 'LinkBase' }],
            ]),
            wildcards: [],
          },
        ],
        [linkTsx, { named: new Map(), wildcards: [] }],
        [linkBaseTsx, { named: new Map(), wildcards: [] }],
      ]),
    });

    const deps = await cache.resolveOnce(story);

    expect(deps.has(linkTsx)).toBe(true);
    expect(deps.has(linkBaseTsx)).toBe(false);
  });

  it('falls back to including the barrel when the name is not found anywhere in the chain', async () => {
    const barrelA = '/repo/lib/ui/index.ts';
    const story = '/repo/story.tsx';

    const cache = makeCache({
      edges: new Map([
        [story, [{ specifier: '@ui', importedNames: new Set(['NonExistent']), kind: 'static' }]],
      ]),
      resolutions: new Map([[`${story}::@ui`, barrelA]]),
      barrelInfos: new Map([
        [
          barrelA,
          {
            named: new Map([['Button', { specifier: './Button.tsx', importedName: 'Button' }]]),
            wildcards: [],
          },
        ],
      ]),
    });

    const deps = await cache.resolveOnce(story);

    expect(deps.has(barrelA)).toBe(true);
  });

  it('handles cyclic barrel re-exports without infinite looping', async () => {
    const barrelA = '/repo/lib/a/index.ts';
    const barrelB = '/repo/lib/b/index.ts';
    const story = '/repo/story.tsx';

    const cache = makeCache({
      edges: new Map([
        [story, [{ specifier: '@ui', importedNames: new Set(['Foo']), kind: 'static' }]],
      ]),
      resolutions: new Map([
        [`${story}::@ui`, barrelA],
        [`${barrelA}::../b`, barrelB],
        [`${barrelB}::../a`, barrelA],
      ]),
      barrelInfos: new Map([
        [barrelA, { named: new Map(), wildcards: ['../b'] }],
        [barrelB, { named: new Map(), wildcards: ['../a'] }],
      ]),
    });

    const deps = await cache.resolveOnce(story);

    // Cycle detected → needBarrel=true → barrel A added as conservative fallback
    expect(deps.has(barrelA)).toBe(true);
  });

  it('resolves a name that the barrel re-exports as export type { ... }', async () => {
    // Barrel: export { Link } from './Link'; export type { ButtonType } from './types'
    // Story imports { Link, ButtonType } without the `type` keyword.
    // ButtonType must be followed to types.ts even though it's a type re-export.
    const barrel = '/repo/lib/ui/index.ts';
    const linkTsx = '/repo/lib/ui/Link.tsx';
    const typesTsx = '/repo/lib/ui/types.ts';
    const story = '/repo/story.tsx';

    const cache = makeCache({
      edges: new Map([
        [
          story,
          [{ specifier: '@ui', importedNames: new Set(['Link', 'ButtonType']), kind: 'static' }],
        ],
      ]),
      resolutions: new Map([
        [`${story}::@ui`, barrel],
        [`${barrel}::./Link.tsx`, linkTsx],
        [`${barrel}::./types.ts`, typesTsx],
      ]),
      barrelInfos: new Map([
        [
          barrel,
          {
            named: new Map([
              ['Link', { specifier: './Link.tsx', importedName: 'Link' }],
              // type re-export — parseBarrelInfo must include it
              ['ButtonType', { specifier: './types.ts', importedName: 'ButtonType' }],
            ]),
            wildcards: [],
          },
        ],
        [linkTsx, { named: new Map(), wildcards: [] }],
        [typesTsx, { named: new Map(), wildcards: [] }],
      ]),
    });

    const deps = await cache.resolveOnce(story);

    expect(deps.has(linkTsx)).toBe(true);
    expect(deps.has(typesTsx)).toBe(true);
    expect(deps.has(barrel)).toBe(true);
  });

  it('stops at MAX_DEPTH and falls back to needBarrel when chain exceeds 10 hops', async () => {
    // 12 barrels chained via wildcards; Foo lives at the end (hop 11), past the limit.
    const story = '/repo/story.tsx';
    const barrels = Array.from({ length: 12 }, (_, i) => `/repo/lib/barrel${i}/index.ts`);

    const resolutions: Resolutions = new Map([[`${story}::@ui`, barrels[0]]]);
    const barrelInfos: BarrelInfoMap = new Map();

    for (let i = 0; i < barrels.length - 1; i++) {
      resolutions.set(`${barrels[i]}::./next`, barrels[i + 1]);
      barrelInfos.set(barrels[i], { named: new Map(), wildcards: ['./next'] });
    }
    barrelInfos.set(barrels[barrels.length - 1], {
      named: new Map([['Foo', { specifier: './Foo.tsx', importedName: 'Foo' }]]),
      wildcards: [],
    });
    resolutions.set(`${barrels[barrels.length - 1]}::./Foo.tsx`, '/repo/lib/Foo.tsx');

    const cache = makeCache({
      edges: new Map([
        [story, [{ specifier: '@ui', importedNames: new Set(['Foo']), kind: 'static' }]],
      ]),
      resolutions,
      barrelInfos,
    });

    const deps = await cache.resolveOnce(story);

    // Chain too deep — Foo.tsx not reachable; falls back to including barrel[0]
    expect(deps.has(barrels[0])).toBe(true);
    expect(deps.has('/repo/lib/Foo.tsx')).toBe(false);
  });
});

import { readFile } from 'node:fs/promises';

import { normalize } from 'pathe';

import { parseBarrelInfo } from 'storybook/internal/oxc-parser';
import type { BarrelInfo } from 'storybook/internal/oxc-parser';

import type { ParserRegistry } from '../parser-registry/parser-registry.ts';
import type { ImportEdge } from './types.ts';
import type { ChangeDetectionResolverFactory } from './resolver-factory.ts';
import { isInScope } from './scope.ts';

/** Maximum barrel-chain hops followed when tracing a named export to its source file. */
const BARREL_FOLLOW_MAX_DEPTH = 10;

interface CacheLogger {
  debug: (message: string) => void;
  warn: (message: string) => void;
}

interface CacheOptions {
  registry: ParserRegistry;
  resolver: ChangeDetectionResolverFactory;
  workspaceRoots: Set<string>;
  projectRoot: string;
  logger: CacheLogger;
  /** When true, accumulates barrel resolution events retrievable via {@link getBarrelTrace}. */
  debug?: boolean;
}

export interface BarrelResolutionEvent {
  /** File that contained the import statement. */
  from: string;
  /** Raw import specifier as written in source. */
  specifier: string;
  /** Resolved absolute path of the barrel file. */
  barrel: string;
  /** Named symbols that were requested. */
  names: string[];
  /** Source files the names resolved to (empty when needBarrel is true for all names). */
  resolved: string[];
  /**
   * True when at least one name could not be chain-followed — the barrel itself was
   * added to the dep set as a conservative fallback.
   */
  needBarrel: boolean;
}

/**
 * Long-lived parse + resolve cache shared across cold-start build and incremental patch.
 *
 * Both layers were re-parsing and re-resolving every shared module on every walk before
 * this cache existed (`DependencyGraphBuilder` had per-build caches; the patcher had none
 * at all). Promoting the caches to instance scope and invalidating on file-change events
 * collapses the redundant work without sacrificing correctness — `change`/`unlink` events
 * call {@link invalidate} before the patcher reads, so a stale entry can never survive.
 */
export class ParseResolveCache {
  private readonly registry: ParserRegistry;
  private readonly resolver: ChangeDetectionResolverFactory;
  private readonly workspaceRoots: Set<string>;
  private readonly projectRoot: string;
  private readonly logger: CacheLogger;

  private readonly parseCache = new Map<string, Promise<ImportEdge[]>>();
  private readonly resolveCache = new Map<string, Promise<Set<string>>>();
  private readonly barrelInfoCache = new Map<string, Promise<BarrelInfo>>();
  private readonly debugTrace: BarrelResolutionEvent[] | null;

  constructor(opts: CacheOptions) {
    this.registry = opts.registry;
    this.resolver = opts.resolver;
    this.workspaceRoots = new Set(Array.from(opts.workspaceRoots, (r) => normalize(r)));
    this.projectRoot = normalize(opts.projectRoot);
    this.logger = opts.logger;
    this.debugTrace = opts.debug ? [] : null;
  }

  /** Returns accumulated barrel resolution events, or null when debug mode is off. */
  getBarrelTrace(): BarrelResolutionEvent[] | null {
    return this.debugTrace;
  }

  /**
   * Parses the file once and caches the resulting edge list. Returns `[]` for unreadable
   * files, parse failures, or files whose extension has no registered parser — callers
   * cannot distinguish between "no edges" and "we couldn't look", which is by design:
   * either way the file contributes nothing to the dependency graph.
   */
  parseOnce(filePath: string): Promise<ImportEdge[]> {
    const existing = this.parseCache.get(filePath);
    if (existing) {
      return existing;
    }
    const promise = (async (): Promise<ImportEdge[]> => {
      let source: string;
      try {
        source = await readFile(filePath, 'utf8');
      } catch (error) {
        this.logger.debug(
          `Change detection: could not read ${filePath}: ${error instanceof Error ? error.message : String(error)}`
        );
        return [];
      }
      try {
        return (await this.registry.parse(filePath, source)) ?? [];
      } catch (error) {
        this.logger.debug(
          `Change detection: failed to parse ${filePath}: ${error instanceof Error ? error.message : String(error)}`
        );
        return [];
      }
    })();
    this.parseCache.set(filePath, promise);
    return promise;
  }

  /** Resolves every in-scope edge declared by `filePath` and returns the dep Set. */
  resolveOnce(filePath: string): Promise<Set<string>> {
    const existing = this.resolveCache.get(filePath);
    if (existing) {
      return existing;
    }
    const promise = (async (): Promise<Set<string>> => {
      const edges = await this.parseOnce(filePath);
      const deps = new Set<string>();
      for (const edge of edges) {
        const resolved = await this.resolver.resolve(filePath, edge.specifier);
        if (resolved === null) {
          this.logger.debug(`Could not resolve ${edge.specifier} from ${filePath}`);
          continue;
        }
        const normalised = normalize(resolved);
        if (!isInScope(normalised, this.projectRoot, this.workspaceRoots)) {
          continue;
        }

        // For named imports, attempt to follow barrel re-exports directly to
        // the source files of the specific symbols used.  This prevents stories
        // that import only `Button` from being marked as related when
        // `Breadcrumb` (also exported by the same barrel) changes.
        if (edge.importedNames !== null && edge.importedNames.size > 0) {
          const { sources, barrels, needBarrel } = await this.followBarrel(
            normalised,
            edge.importedNames
          );
          this.debugTrace?.push({
            from: filePath,
            specifier: edge.specifier,
            barrel: normalised,
            names: Array.from(edge.importedNames),
            resolved: Array.from(sources),
            needBarrel,
          });
          for (const src of sources) {
            deps.add(src);
          }
          // Add every barrel visited during chain-following so that structural re-export
          // changes at any hop (not just the direct import) invalidate this importer.
          for (const barrel of barrels) {
            deps.add(barrel);
          }
        }

        deps.add(normalised);
      }
      return deps;
    })();
    this.resolveCache.set(filePath, promise);
    return promise;
  }

  /**
   * For each name in `requestedNames`, walks the barrel chain starting at `barrelPath`
   * until it reaches the actual source file that defines the symbol.  Handles multi-level
   * chains where intermediate barrels use `export * from '...'` by recursing through them.
   *
   * Returns `needBarrel = true` for any name that could not be fully resolved so the
   * caller falls back to including the barrel itself.
   */
  private async followBarrel(
    barrelPath: string,
    requestedNames: Set<string>
  ): Promise<{ sources: Set<string>; barrels: Set<string>; needBarrel: boolean }> {
    const barrels = new Set<string>();
    const results = await Promise.all(
      Array.from(requestedNames, (name) => this.followName(barrelPath, name, new Set(), 0, barrels))
    );
    const sources = new Set<string>();
    let needBarrel = false;
    for (const source of results) {
      if (source !== null) {
        sources.add(source);
      } else {
        needBarrel = true;
      }
    }
    return { sources, barrels, needBarrel };
  }

  /**
   * Recursively follows a single exported name through barrel re-exports.
   *
   * 1. Checks named re-exports in `barrelPath`; if found, resolves the specifier and
   *    recurses with the inner name in case the target is itself a barrel.
   * 2. Falls through to wildcard re-exports (`export * from '...'`) and searches each
   *    transitively until the name is found or all paths are exhausted.
   *
   * Returns the normalised absolute path of the first non-barrel source found, or `null`
   * when the chain is unresolvable (triggering the conservative `needBarrel` fallback).
   * Cycle detection via `visited`; depth limit of 10 hops prevents infinite recursion.
   */
  private async followName(
    barrelPath: string,
    name: string,
    visited: Set<string>,
    depth: number,
    barrels: Set<string>
  ): Promise<string | null> {
    if (depth > BARREL_FOLLOW_MAX_DEPTH) {
      this.logger.debug(
        `Change detection: barrel chain depth limit reached at ${barrelPath} (looking for "${name}")`
      );
      return null;
    }
    if (visited.has(barrelPath)) {
      return null;
    }
    visited.add(barrelPath);
    barrels.add(barrelPath);

    const info = await this.barrelInfoOnce(barrelPath);

    // NOTE: parseBarrelInfo only tracks direct re-exports (export { x } from './y').
    // Two-step re-exports (import { x } from './y'; export { x }) are not detected,
    // causing the barrel fallback to be used for those patterns.
    const entry = info.named.get(name);
    if (entry) {
      const sourceResolved = await this.resolver.resolve(barrelPath, entry.specifier);
      if (sourceResolved !== null) {
        const sourceNorm = normalize(sourceResolved);
        if (isInScope(sourceNorm, this.projectRoot, this.workspaceRoots)) {
          const deeper = await this.followName(
            sourceNorm,
            entry.importedName,
            new Set(visited),
            depth + 1,
            barrels
          );
          return deeper ?? sourceNorm;
        }
      }
      return null;
    }

    // NOTE: namespace re-exports (export * as ns from './foo') are not tracked.
    // Imports using the namespace form (ns.Button) fall back to barrel tracking.
    for (const wildcardSpec of info.wildcards) {
      const wildcardResolved = await this.resolver.resolve(barrelPath, wildcardSpec);
      if (wildcardResolved === null) {
        continue;
      }
      const wildcardNorm = normalize(wildcardResolved);
      if (!isInScope(wildcardNorm, this.projectRoot, this.workspaceRoots)) {
        continue;
      }
      const result = await this.followName(
        wildcardNorm,
        name,
        new Set(visited),
        depth + 1,
        barrels
      );
      if (result !== null) {
        return result;
      }
    }

    return null;
  }

  /**
   * Lazily parses and caches the barrel info (named re-exports + wildcard specifiers)
   * for `filePath`. Returns empty info for files that cannot be read or have no exports.
   */
  private barrelInfoOnce(filePath: string): Promise<BarrelInfo> {
    const existing = this.barrelInfoCache.get(filePath);
    if (existing) {
      return existing;
    }
    const promise = (async (): Promise<BarrelInfo> => {
      let source: string;
      try {
        source = await readFile(filePath, 'utf8');
      } catch {
        return { named: new Map(), wildcards: [] };
      }
      try {
        return await parseBarrelInfo(filePath, source);
      } catch {
        return { named: new Map(), wildcards: [] };
      }
    })();
    this.barrelInfoCache.set(filePath, promise);
    return promise;
  }

  /** Drops all cached entries for `filePath`. Call on every `change`/`unlink` event. */
  invalidate(filePath: string): void {
    this.parseCache.delete(filePath);
    this.resolveCache.delete(filePath);
    this.barrelInfoCache.delete(filePath);
  }

  /** Test-only: full reset. */
  clear(): void {
    this.parseCache.clear();
    this.resolveCache.clear();
    this.barrelInfoCache.clear();
  }
}

/**
 * Integration tests for ChangeDetectionResolverFactory alias and tsconfig path resolution.
 *
 * These tests use real file system access and the real oxc-resolver binary so that we catch
 * oxc-resolver behavioural differences (e.g. trailing-slash alias keys not working, tsconfig
 * path resolution) rather than just testing our own normalisation logic.
 */
import { mkdirSync, mkdtempSync, realpathSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { ChangeDetectionResolverFactory } from './resolver-factory.ts';

let dir: string;

beforeEach(() => {
  // realpathSync resolves macOS /var → /private/var symlink so path comparisons work
  dir = realpathSync(mkdtempSync(join(tmpdir(), 'sb-resolver-test-')));
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

function write(relPath: string, content = 'export {};') {
  const abs = join(dir, relPath);
  mkdirSync(join(dir, relPath, '..'), { recursive: true });
  writeFileSync(abs, content);
  return abs;
}

function tsconfig(compilerOptions: Record<string, unknown>, filename = 'tsconfig.json') {
  const abs = join(dir, filename);
  writeFileSync(abs, JSON.stringify({ compilerOptions }));
  return abs;
}

describe('ChangeDetectionResolverFactory', () => {
  describe('no alias, no tsconfig', () => {
    it('resolves relative imports', async () => {
      const a = write('src/a.ts');
      const b = write('src/b.ts');
      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(a, './b')).toBe(b);
    });

    it('returns null for bare specifiers without node_modules', async () => {
      const a = write('src/a.ts');
      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(a, 'react')).toBeNull();
    });
  });

  describe('explicit alias (Record form)', () => {
    it('resolves alias to absolute path', async () => {
      const target = write('src/utils/index.ts');
      const from = write('src/components/Foo.ts');
      const r = new ChangeDetectionResolverFactory({
        projectRoot: dir,
        alias: { utils: join(dir, 'src/utils') },
      });
      expect(await r.resolve(from, 'utils/index')).toBe(target);
    });

    it('strips trailing slash from alias key (oxc-resolver does not support @/ prefix keys)', async () => {
      const target = write('src/app/Component.ts');
      const from = write('src/pages/Page.ts');
      // "@/" with trailing slash would fail in raw oxc-resolver; we normalise it to "@"
      const r = new ChangeDetectionResolverFactory({
        projectRoot: dir,
        alias: { '@/': join(dir, 'src') + '/' },
      });
      expect(await r.resolve(from, '@/app/Component')).toBe(target);
    });
  });

  describe('explicit alias (Array form)', () => {
    it('resolves array alias with string find', async () => {
      const target = write('src/utils/helper.ts');
      const from = write('src/a.ts');
      const r = new ChangeDetectionResolverFactory({
        projectRoot: dir,
        alias: [{ find: 'utils', replacement: join(dir, 'src/utils') }],
      });
      expect(await r.resolve(from, 'utils/helper')).toBe(target);
    });

    it('strips trailing slash from array alias find', async () => {
      const target = write('src/shared/util.ts');
      const from = write('src/a.ts');
      const r = new ChangeDetectionResolverFactory({
        projectRoot: dir,
        alias: [{ find: '~@/', replacement: join(dir, 'src') + '/' }],
      });
      expect(await r.resolve(from, '~@/shared/util')).toBe(target);
    });

    it('returns null and does not throw for regex aliases (unsupported, opaque-leaf)', async () => {
      const from = write('src/a.ts');
      write('src/utils/foo.ts');
      const r = new ChangeDetectionResolverFactory({
        projectRoot: dir,
        alias: [{ find: /^utils\/(.*)/, replacement: join(dir, 'src/utils/$1') }],
      });
      expect(await r.resolve(from, 'utils/foo')).toBeNull();
    });
  });

  describe('tsconfig path aliases (auto-discovered via resolveFileAsync)', () => {
    it('resolves standard wildcard pattern "@/*"', async () => {
      const target = write('src/components/Button.tsx');
      const from = write('src/pages/Home.tsx');
      tsconfig({ baseUrl: '.', paths: { '@/*': ['./*'] } });
      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, '@/src/components/Button')).toBe(target);
    });

    it('resolves named wildcard pattern "components/*"', async () => {
      const target = write('src/ui/Button.tsx');
      const from = write('src/pages/Home.tsx');
      tsconfig({ baseUrl: '.', paths: { 'components/*': ['src/ui/*'] } });
      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, 'components/Button')).toBe(target);
    });

    it('resolves multiple tsconfig path entries', async () => {
      const btn = write('src/ui/Button.tsx');
      const util = write('src/helpers/format.ts');
      const from = write('src/pages/Home.tsx');
      tsconfig({
        baseUrl: '.',
        paths: {
          'components/*': ['src/ui/*'],
          'helpers/*': ['src/helpers/*'],
        },
      });
      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, 'components/Button')).toBe(btn);
      expect(await r.resolve(from, 'helpers/format')).toBe(util);
    });

    it('explicit alias and tsconfig wildcard paths resolve consistently', async () => {
      const target = write('src/ui/Button.tsx');
      const from = write('src/pages/Home.tsx');
      tsconfig({ baseUrl: '.', paths: { '@/*': ['src/ui/*'] } });
      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, '@/Button')).toBe(target);
    });

    it('returns null for tsconfig path alias when no tsconfig exists', async () => {
      const from = write('src/a.ts');
      // No tsconfig.json written — @/* has no resolver backing
      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, '@/src/a')).toBeNull();
    });

    it('handles tsconfig without baseUrl (paths relative to tsconfig dir)', async () => {
      const target = write('src/components/Button.tsx');
      const from = write('src/pages/Home.tsx');
      // No baseUrl — TypeScript resolves paths relative to tsconfig dir
      tsconfig({ paths: { '@/*': ['src/*'] } });
      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, '@/components/Button')).toBe(target);
    });

    it('resolves "@/*": ["./*"] from deeply nested source file (dify-plus pattern)', async () => {
      // Reproduces: @/app/components/base/icons/IconBase unresolved from
      // app/components/base/icons/src/vender/line/others/Tools.tsx
      // oxc-resolver's resolveFileAsync walks up from the file to find tsconfig.json
      const target = write('app/components/base/icons/IconBase.tsx');
      const from = write('app/components/base/icons/src/vender/line/others/Tools.tsx');
      tsconfig({ paths: { '@/*': ['./*'], '~@/*': ['./*'] } });
      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, '@/app/components/base/icons/IconBase')).toBe(target);
    });
  });

  /**
   * Yarn-workspace cross-package resolution
   *
   * In a monorepo the root `tsconfig.json` typically maps workspace package names to their
   * source directories (e.g. "@mantinex/*" -> ["./packages/@mantinex/ * /src"]).  Per-package
   * tsconfigs often do NOT extend the root, so `tsconfig: 'auto'` only sees the nearest
   * (package-level) tsconfig and misses these workspace paths -> NotFound("@mantinex/demo").
   *
   * The fix in ResolverFactory uses the root tsconfig explicitly when it exists, so that
   * workspace-level path mappings are always consulted.
   */
  describe('yarn workspace cross-package resolution', () => {
    it('resolves workspace sibling via root tsconfig paths when package-level tsconfig has no mapping', async () => {
      // Reproduces: @mantinex/demo unresolved from packages/@docs/demos/src/.../YearPicker/
      // Root tsconfig has "@mantinex/*" paths; package tsconfig has no paths and no extends.
      const target = write('packages/@mantinex/demo/src/index.ts');
      // Package-level tsconfig — no paths, no extends (mirrors real mantine setup)
      mkdirSync(join(dir, 'packages/@docs/demos'), { recursive: true });
      writeFileSync(
        join(dir, 'packages/@docs/demos/tsconfig.json'),
        JSON.stringify({ compilerOptions: {} })
      );
      // Root tsconfig — maps workspace packages to source directories
      tsconfig({ paths: { '@mantinex/*': ['./packages/@mantinex/*/src'] } });
      const from = write(
        'packages/@docs/demos/src/demos/dates/YearPicker/YearPicker.demo.controlProps.tsx'
      );

      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, '@mantinex/demo')).toBe(target);
    });

    it('resolves workspace sibling via node_modules symlink (yarn workspaces classic linker)', async () => {
      // yarn workspace classic linker symlinks workspace packages at root node_modules.
      // The resolver must traverse up past sub-package boundaries to reach root node_modules.
      const target = write('packages/@mantinex/demo/src/index.ts');
      writeFileSync(
        join(dir, 'packages/@mantinex/demo/package.json'),
        JSON.stringify({ name: '@mantinex/demo', main: './src/index.ts' })
      );
      const from = write('packages/@docs/demos/src/demos/dates/YearPicker/file.tsx');

      mkdirSync(join(dir, 'node_modules/@mantinex'), { recursive: true });
      symlinkSync(
        join(dir, 'packages/@mantinex/demo'),
        join(dir, 'node_modules/@mantinex/demo'),
        'dir'
      );

      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, '@mantinex/demo')).toBe(target);
    });

    it('resolves multiple workspace siblings from the same root tsconfig paths', async () => {
      const demoTarget = write('packages/@mantinex/demo/src/index.ts');
      const iconsTarget = write('packages/@mantinex/dev-icons/src/index.ts');
      tsconfig({
        paths: {
          '@mantinex/*': ['./packages/@mantinex/*/src'],
        },
      });
      const from = write('packages/@docs/demos/src/file.tsx');

      const r = new ChangeDetectionResolverFactory({ projectRoot: dir });
      expect(await r.resolve(from, '@mantinex/demo')).toBe(demoTarget);
      expect(await r.resolve(from, '@mantinex/dev-icons')).toBe(iconsTarget);
    });
  });
});

import { join } from 'pathe';

import { ResolverFactory as OxcResolverFactory } from 'oxc-resolver';

import { logger } from 'storybook/internal/node-logger';

import type { ModuleResolveConfig } from '../adapters/types.ts';

const DEFAULT_EXTENSIONS = ['.tsx', '.ts', '.d.ts', '.jsx', '.js', '.mjs', '.cjs', '.json'];
const DEFAULT_CONDITIONS = ['storybook', 'import', 'module', 'default'];

/**
 * `ModuleResolveConfig.alias` accepts both Vite shapes:
 *   - `Record<string, string>` (object form)
 *   - `Array<{ find: string | RegExp; replacement: string }>` (array form)
 *
 * `oxc-resolver` expects `Record<string, Array<string | undefined | null>>`.
 * RegExp `find` entries cannot be expressed in oxc-resolver's alias config and
 * are skipped with a debug log (downgraded to opaque-leaf at resolve time).
 *
 * Instance-scoped so each ChangeDetectionResolverFactory warns independently —
 * multiple service instances in the same process do not suppress each other's warnings.
 */
class AliasNormalizer {
  private readonly warnedRegexAliases = new Set<string>();

  normalize(
    alias: ModuleResolveConfig['alias']
  ): Record<string, Array<string | undefined | null>> | undefined {
    if (!alias) {
      return undefined;
    }

    const out: Record<string, Array<string | undefined | null>> = {};
    const skippedRegex: string[] = [];

    if (Array.isArray(alias)) {
      for (const entry of alias) {
        if (typeof entry.find === 'string') {
          const find = entry.find.replace(/\/$/, '');
          const replacement = entry.replacement.replace(/\/$/, '');
          out[find] = [replacement];
        } else {
          skippedRegex.push(String(entry.find));
        }
      }
    } else {
      for (const [find, replacement] of Object.entries(alias)) {
        out[find.replace(/\/$/, '')] = [replacement.replace(/\/$/, '')];
      }
    }

    if (skippedRegex.length > 0) {
      const newPatterns = skippedRegex.filter((p) => !this.warnedRegexAliases.has(p));
      if (newPatterns.length > 0) {
        for (const p of newPatterns) {
          this.warnedRegexAliases.add(p);
        }
        logger.debug(
          `Change detection: ignored ${skippedRegex.length} regex alias(es); related modules tracked as opaque-leaf.`
        );
        logger.debug(
          `ChangeDetectionResolverFactory: skipped regex aliases [${skippedRegex.join(', ')}]`
        );
      } else {
        for (const pattern of skippedRegex) {
          logger.debug(`ChangeDetectionResolverFactory: skipping regex alias '${pattern}'`);
        }
      }
    }

    return Object.keys(out).length > 0 ? out : undefined;
  }
}

/**
 * Thin wrapper around `oxc-resolver`'s `ResolverFactory` configured per a
 * builder-supplied {@link ModuleResolveConfig}. Normalizes the alias map shape and
 * converts resolver errors to `null` (with a debug log) — the caller treats
 * unresolvable specifiers as opaque-leaf edges.
 */
export class ChangeDetectionResolverFactory {
  private readonly factory: OxcResolverFactory;
  private readonly aliasNormalizer = new AliasNormalizer();
  /**
   * Virtual entry point placed directly in the project root.
   *
   * Used as the fallback `from` path when the primary resolution fails.
   * Resolving from here guarantees that `resolveFileAsync`'s tsconfig
   * walk-up reaches the root `tsconfig.json` before any intermediate
   * per-package tsconfig — so workspace-level `paths` mappings are
   * consulted even when the per-package tsconfig does not extend root.
   */
  private readonly projectRootEntry: string;

  constructor(config: ModuleResolveConfig) {
    const alias = this.aliasNormalizer.normalize(config.alias);
    const conditionNames = config.conditions ?? DEFAULT_CONDITIONS;

    this.factory = new OxcResolverFactory({
      tsconfig: 'auto',
      alias,
      conditionNames,
      extensions: DEFAULT_EXTENSIONS,
    });

    this.projectRootEntry = join(config.projectRoot, '__sb_resolver_root__.ts');
  }

  /**
   * Resolves `specifier` from the file at `from` (must be an absolute path).
   *
   * Two-pass strategy:
   * 1. Resolve from `from` — handles per-package tsconfig paths and local node_modules.
   * 2. On failure, retry from the project root — picks up root-level tsconfig `paths`
   *    (e.g. workspace package aliases) that intermediate per-package tsconfigs may
   *    not inherit, as well as root-level node_modules symlinks.
   *
   * Returns the absolute resolved path, or `null` if both passes fail.
   * Never throws — internal errors are converted to `null` and a debug-level log
   * line is emitted.
   */
  async resolve(from: string, specifier: string): Promise<string | null> {
    try {
      const result = await this.factory.resolveFileAsync(from, specifier);
      if (result.path) {
        return result.path;
      }

      // Fallback: retry from the project root so that root-level tsconfig paths
      // and root node_modules are consulted.  Skip the fallback when `from` is
      // already the virtual root entry to avoid a redundant second attempt.
      if (from !== this.projectRootEntry) {
        const rootResult = await this.factory.resolveFileAsync(this.projectRootEntry, specifier);
        if (rootResult.path) {
          return rootResult.path;
        }
        if (result.error ?? rootResult.error) {
          logger.debug(
            `ChangeDetectionResolverFactory: '${specifier}' from '${from}' unresolved (${result.error ?? rootResult.error})`
          );
        }
        return null;
      }

      if (result.error) {
        logger.debug(
          `ChangeDetectionResolverFactory: '${specifier}' from '${from}' unresolved (${result.error})`
        );
      }
      return null;
    } catch (error) {
      logger.debug(
        `ChangeDetectionResolverFactory: error resolving '${specifier}' from '${from}': ${String(error)}`
      );
      return null;
    }
  }
}

// Covers the construction + mutation surface of ReverseIndexImpl.
import { describe, expect, it } from 'vitest';

import { ReverseIndexImpl } from './reverse-index.ts';

describe('ReverseIndexImpl', () => {
  it('returns an empty Map (not undefined) when looking up an unknown dep', () => {
    const index = new ReverseIndexImpl();

    const result = index.lookup('/repo/src/foo.ts');

    expect(result).toBeInstanceOf(Map);
    expect(result.size).toBe(0);
  });

  it('records (dep, story, depth) and surfaces the depth via lookup', () => {
    const index = new ReverseIndexImpl();

    index.record('/repo/src/foo.ts', '/repo/src/Foo.stories.tsx', 1);

    const result = index.lookup('/repo/src/foo.ts');
    expect(result.get('/repo/src/Foo.stories.tsx')).toBe(1);
  });

  it('keeps min(existing, depth) when the same (dep, story) is recorded twice with different depths', () => {
    const index = new ReverseIndexImpl();

    index.record('/repo/src/foo.ts', '/repo/src/A.stories.tsx', 3);
    index.record('/repo/src/foo.ts', '/repo/src/A.stories.tsx', 1);
    index.record('/repo/src/foo.ts', '/repo/src/A.stories.tsx', 2);

    expect(index.lookup('/repo/src/foo.ts').get('/repo/src/A.stories.tsx')).toBe(1);
  });

  it('records the same dep against multiple stories and surfaces both via lookup', () => {
    const index = new ReverseIndexImpl();

    index.record('/repo/src/shared.ts', '/repo/src/A.stories.tsx', 1);
    index.record('/repo/src/shared.ts', '/repo/src/B.stories.tsx', 2);

    const result = index.lookup('/repo/src/shared.ts');
    expect(result.size).toBe(2);
    expect(result.get('/repo/src/A.stories.tsx')).toBe(1);
    expect(result.get('/repo/src/B.stories.tsx')).toBe(2);
  });

  it('removeStory deletes the story from every inner map and prunes outer entries that become empty', () => {
    const index = new ReverseIndexImpl();
    index.record('/repo/src/x.ts', '/repo/src/A.stories.tsx', 1);
    index.record('/repo/src/x.ts', '/repo/src/B.stories.tsx', 2);
    index.record('/repo/src/y.ts', '/repo/src/A.stories.tsx', 1);

    index.removeStory('/repo/src/A.stories.tsx');

    // /repo/src/y.ts had only A — should be pruned.
    expect(index.asMap().has('/repo/src/y.ts')).toBe(false);
    // /repo/src/x.ts retained for B; A removed.
    const inner = index.lookup('/repo/src/x.ts');
    expect(inner.size).toBe(1);
    expect(inner.get('/repo/src/B.stories.tsx')).toBe(2);
    expect(inner.has('/repo/src/A.stories.tsx')).toBe(false);
  });

  it('removeEdge removes only the (dep, story) pair without touching other stories', () => {
    const index = new ReverseIndexImpl();
    index.record('/repo/src/x.ts', '/repo/src/A.stories.tsx', 1);
    index.record('/repo/src/x.ts', '/repo/src/B.stories.tsx', 2);

    index.removeEdge('/repo/src/x.ts', '/repo/src/A.stories.tsx');

    const inner = index.lookup('/repo/src/x.ts');
    expect(inner.has('/repo/src/A.stories.tsx')).toBe(false);
    expect(inner.get('/repo/src/B.stories.tsx')).toBe(2);
  });

  it('removeEdge prunes the outer entry when it becomes empty', () => {
    const index = new ReverseIndexImpl();
    index.record('/repo/src/x.ts', '/repo/src/A.stories.tsx', 1);

    index.removeEdge('/repo/src/x.ts', '/repo/src/A.stories.tsx');

    expect(index.asMap().has('/repo/src/x.ts')).toBe(false);
  });

  it('handles cycles by retaining the minimum depth across multiple recordings', () => {
    // A imports B (depth 1); B imports C (depth 2); C imports B (would be depth 3).
    // Whatever order build() visits in, recording min keeps depth 1 for B and 2 for C from story A.
    const index = new ReverseIndexImpl();
    index.record('/repo/src/B.ts', '/repo/src/A.stories.tsx', 1);
    index.record('/repo/src/C.ts', '/repo/src/A.stories.tsx', 2);
    // Cycle re-entry attempts:
    index.record('/repo/src/B.ts', '/repo/src/A.stories.tsx', 3);
    index.record('/repo/src/C.ts', '/repo/src/A.stories.tsx', 4);

    expect(index.lookup('/repo/src/B.ts').get('/repo/src/A.stories.tsx')).toBe(1);
    expect(index.lookup('/repo/src/C.ts').get('/repo/src/A.stories.tsx')).toBe(2);
  });
});

import type { ReverseIndex } from './types.ts';

/**
 * In-memory reverse index from dep file → story file → shortest breadth-first-search depth.
 *
 * **Contract:** callers MUST pass already-normalised paths (`pathe.normalize`); the index
 * does not re-normalise on each mutation. Producers in `DependencyGraphBuilder` and
 * `IncrementalPatcher` already normalise at the boundary.
 */
export class ReverseIndexImpl {
  private readonly index: ReverseIndex = new Map();
  /** Forward mapping from story file -> Set of dep files it reaches. */
  private readonly forwardIndex = new Map<string, Set<string>>();

  /** Records (or updates with min) the depth for (dep, story). */
  record(dep: string, story: string, depth: number): void {
    let inner = this.index.get(dep);
    if (!inner) {
      inner = new Map<string, number>();
      this.index.set(dep, inner);
    }
    const previous = inner.get(story);
    if (previous === undefined || depth < previous) {
      inner.set(story, depth);

      let deps = this.forwardIndex.get(story);
      if (!deps) {
        deps = new Set<string>();
        this.forwardIndex.set(story, deps);
      }
      deps.add(dep);
    }
  }

  /** Removes a story from every inner map; prunes outer entries that become empty. */
  removeStory(story: string): void {
    const deps = this.forwardIndex.get(story);
    if (!deps) {
      return;
    }
    for (const dep of deps) {
      const inner = this.index.get(dep);
      if (inner) {
        inner.delete(story);
        if (inner.size === 0) {
          this.index.delete(dep);
        }
      }
    }
    this.forwardIndex.delete(story);
  }

  /** Removes a single (dep, story) pair without affecting other stories' depths to that dep. */
  removeEdge(dep: string, story: string): void {
    const inner = this.index.get(dep);
    if (!inner) {
      return;
    }
    if (inner.delete(story)) {
      if (inner.size === 0) {
        this.index.delete(dep);
      }
      const deps = this.forwardIndex.get(story);
      if (deps) {
        deps.delete(dep);
        if (deps.size === 0) {
          this.forwardIndex.delete(story);
        }
      }
    }
  }

  /** Returns the per-story depth map for dep. EMPTY map (not undefined) if dep unknown. */
  lookup(dep: string): Map<string, number> {
    return this.index.get(dep) ?? new Map<string, number>();
  }

  /** Internal state inspection — for tests. */
  asMap(): ReverseIndex {
    return this.index;
  }
}

const NODE_MODULES_SEGMENT = '/node_modules/';

export function isInsideAnyWorkspace(absolute: string, workspaceRoots: Set<string>): boolean {
  if (absolute.includes(NODE_MODULES_SEGMENT)) {
    return false;
  }
  for (const root of workspaceRoots) {
    if (absolute === root || absolute.startsWith(root.endsWith('/') ? root : `${root}/`)) {
      return true;
    }
  }
  return false;
}

export function isInScope(
  absolute: string,
  projectRoot: string,
  workspaceRoots: Set<string>
): boolean {
  const projectPrefix = projectRoot.endsWith('/') ? projectRoot : `${projectRoot}/`;
  if (
    (absolute === projectRoot || absolute.startsWith(projectPrefix)) &&
    !absolute.includes(NODE_MODULES_SEGMENT)
  ) {
    return true;
  }
  return isInsideAnyWorkspace(absolute, workspaceRoots);
}

import type { ImportEdge } from '../parser-registry/types.ts';

export type { ImportEdge };

/**
 * Reverse index from dep file path → story file → shortest forward-walk depth from that story.
 * Inner number preserves the breadth-first-search hop-count semantics used by
 * `ChangeDetectionService.buildStatuses` to distinguish `modified` (closest stories) from
 * `affected` (farther stories).
 *
 * Keys are absolute paths normalised via `pathe.normalize`.
 */
export type ReverseIndex = Map<string, Map<string, number>>;

/** Per-file outgoing edges, used by IncrementalPatcher to compute diffs. */
export type DependencyGraph = Map<string, Set<string>>;

import type { ParserRegistry } from '../parser-registry/parser-registry.ts';
import type { ParseResolveCache } from './parse-resolve-cache.ts';
import type { ReverseIndexImpl } from './reverse-index.ts';

const MAX_BREADTH_FIRST_SEARCH_DEPTH = 50;

export interface WalkFromStoryArgs {
  storyRoot: string;
  registry: ParserRegistry;
  cache: ParseResolveCache;
  reverseIndex: ReverseIndexImpl;
  /** Called once per visited file with its resolved outgoing dependencies. */
  recordEdges: (file: string, deps: Set<string>) => void;
}

/**
 * Breadth-first-search forward walk from `storyRoot`, parsing + resolving each file once via the
 * shared cache and recording (dep, story, depth) tuples on `reverseIndex`. Stops at non-walkable
 * files (no parser registered).
 */
export async function walkFromStory({
  storyRoot,
  registry,
  cache,
  reverseIndex,
  recordEdges,
}: WalkFromStoryArgs): Promise<void> {
  reverseIndex.record(storyRoot, storyRoot, 0);

  const visited = new Map<string, number>();
  visited.set(storyRoot, 0);
  const queue: Array<{ file: string; depth: number }> = [{ file: storyRoot, depth: 0 }];
  let head = 0;

  while (head < queue.length) {
    const { file, depth } = queue[head++];

    if (registry.parserFor(file) === undefined) {
      continue;
    }

    const resolvedDeps = await cache.resolveOnce(file);
    recordEdges(file, resolvedDeps);

    const nextDepth = depth + 1;
    for (const normalised of resolvedDeps) {
      if (nextDepth > MAX_BREADTH_FIRST_SEARCH_DEPTH) {
        // Skip — prevents unbounded walks in pathological dep trees
        continue;
      }
      const previousDepth = visited.get(normalised);
      if (previousDepth !== undefined && previousDepth <= nextDepth) {
        continue;
      }
      visited.set(normalised, nextDepth);
      reverseIndex.record(normalised, storyRoot, nextDepth);
      queue.push({ file: normalised, depth: nextDepth });
    }
  }
}

