      await oxcImportParser.parse(
        { filePath: '/tmp/a.ts', source: ' invalid  source `' },
        noopContext
      );
    } catch (error) {
      threw = error;
    }
    if (threw !== undefined) {
      expect(threw).toBeInstanceOf(ChangeDetectionFailureError);
    }
  });
});

