import type { ChannelLike } from 'storybook/internal/channels';
import { STORY_INDEX_INVALIDATED } from 'storybook/internal/core-events';
import type { Presets } from 'storybook/internal/types';

import { registerService } from '../../server.ts';
import { moduleGraphServiceDef } from './definition.ts';
import type { ChangeDetectionAdapter } from './engine/adapters/types.ts';
import { ModuleGraphEngine, type ModuleGraphEngineOptions } from './engine/module-graph-engine.ts';
import { errorToErrorLike } from './types.ts';

export type RegisterModuleGraphServiceOptions = {
  channel: ChannelLike;
  getIndex: ModuleGraphEngineOptions['getIndex'];
  workingDir?: string;
  presets?: Presets;
};

/**
 * Deferred builder adapter. Open-service registration runs early in the dev-server boot, but the
 * preview builder that produces the {@link ChangeDetectionAdapter} is only ready later. The
 * dev-server resolves this once the adapter exists; the engine awaits it before building the graph.
 *
 * `resolveChangeDetectionAdapter` is exported directly (rather than wrapped in a helper) so the
 * dev-server can resolve the promise with one import.
 */
let resolveAdapter!: (adapter: ChangeDetectionAdapter | null | undefined) => void;

export const changeDetectionAdapterPromise = new Promise<ChangeDetectionAdapter | null | undefined>(
  (resolve) => {
    resolveAdapter = resolve;
  }
);

export function resolveChangeDetectionAdapter(
  adapter: ChangeDetectionAdapter | null | undefined
): void {
  resolveAdapter(adapter);
}

/**
 * Registers the `core/module-graph` open service, constructs the graph engine, wires state mirroring
 * into the service commands, and listens for story-index invalidation on the server channel. The
 * engine starts once {@link resolveChangeDetectionAdapter} provides the builder adapter.
 *
 * The engine lives for the entire dev-server process, so there is no teardown path: the OS reclaims
 * everything when the process exits.
 */
export function registerModuleGraphService(options: RegisterModuleGraphServiceOptions) {
  const workingDir = options.workingDir ?? process.cwd();
  let engine: ModuleGraphEngine | undefined = undefined;

  const runtime = registerService(
    {
      ...moduleGraphServiceDef,
      initialState: {
        ...moduleGraphServiceDef.initialState,
        workingDir,
      },
    },
    {
      commands: {
        _waitForSettledEngine: {
          handler: async () => {
            await engine!.whenSettled();
          },
        },
      },
    }
  );

  engine = new ModuleGraphEngine({
    getIndex: options.getIndex,
    workingDir,
    presets: options.presets,
    onSnapshot: (storiesByFile) => {
      void runtime.commands._applyGraphSnapshot({ storiesByFile });
    },
    onUpdate: ({ storiesByFile, bumpedStoryFiles }) => {
      void runtime.commands._applyGraphUpdate({ storiesByFile, bumpedStoryFiles });
    },
    onError: (error) => {
      void runtime.commands._setStatus({ value: 'error', error: errorToErrorLike(error) });
    },
    onUnavailable: (reason, error) => {
      void runtime.commands._setStatus({
        value: 'unavailable',
        reason,
        ...(error ? { error: errorToErrorLike(error) } : {}),
      });
    },
  });

  options.channel.on(STORY_INDEX_INVALIDATED, () => {
    engine!.onStoryIndexInvalidated();
  });

  void changeDetectionAdapterPromise.then((adapter) => {
    if (!adapter) {
      void runtime.commands._setStatus({
        value: 'unavailable',
        reason: 'builder does not support change detection',
      });
      return;
    }
    engine!.start(adapter);
  });

  return runtime;
}

import { join, normalize } from 'pathe';

import type { StoryIndex } from '../../../../types/modules/indexer.ts';

/**
 * Maps each story index to its absolute-story-file -> story-id sets, keyed by the index object
 * so repeat calls within a scan/build reuse the result. The story index is referentially stable
 * for a given generation, so identity-keying is safe; the `workingDir` field guards against the
 * (test-only) case of the same index resolved against a different working directory.
 */
const cache = new WeakMap<
  StoryIndex,
  { workingDir: string; storyIdsByFile: Map<string, Set<string>> }
>();

/**
 * Builds (or returns a cached) map from absolute story-file path to the set of story ids declared
 * in that file. Virtual entries are skipped. Shared by the dependency-graph tracker (to derive its
 * story-root set) and the status publisher (to map affected files back to story ids).
 */
export function getStoryIdsByAbsolutePath(
  storyIndex: StoryIndex,
  workingDir: string
): Map<string, Set<string>> {
  const cached = cache.get(storyIndex);
  if (cached && cached.workingDir === workingDir) {
    return cached.storyIdsByFile;
  }

  const storyIdsByFile = new Map<string, Set<string>>();
  Object.values(storyIndex.entries).forEach((entry) => {
    if (entry.type === 'story' && !entry.importPath.startsWith('virtual:')) {
      const filePath = normalize(join(workingDir, entry.importPath));
      const storyIds = storyIdsByFile.get(filePath) ?? new Set<string>();
      storyIds.add(entry.id);
      storyIdsByFile.set(filePath, storyIds);
    }
  });

  cache.set(storyIndex, { workingDir, storyIdsByFile });
  return storyIdsByFile;
}

import { posix, win32 } from 'node:path';

import { normalize } from 'pathe';

import { slash } from '../../../utils/paths.ts';

import type { ReverseIndex } from './engine/dependency-graph/types.ts';

/** JSON-serializable reverse index shape stored in open-service state. */
export type StoriesByFileRecord = Record<string, Record<string, number>>;

export type ErrorLike = {
  message: string;
  name?: string;
  stack?: string;
  cause?: ErrorLike;
};

export type ModuleGraphStatus =
  | { value: 'booting' }
  | { value: 'ready' }
  | { value: 'error'; error: ErrorLike }
  | { value: 'unavailable'; reason: string; error?: ErrorLike };

export type ModuleGraphServiceState = {
  /** Project root used to normalize absolute file paths in query inputs. */
  workingDir: string;
  status: ModuleGraphStatus;
  graphRevision: number;
  storiesByFile: StoriesByFileRecord;
  /**
   * Per-story revision stamps keyed by story-index-style relative path. Each entry holds the
   * {@link graphRevision} at which that story's subgraph last changed. Seeded to `0` for every
   * story at snapshot time so scoped `graphRevision` reads observe existing keys.
   */
  storyChangeRevisions: Record<string, number>;
  latestChangedStoryFiles: string[];
};

export function errorToErrorLike(error: unknown): ErrorLike {
  if (!(error instanceof Error)) {
    return { message: String(error) };
  }

  return {
    message: error.message,
    name: error.name,
    stack: error.stack,
    cause: error.cause === undefined ? undefined : errorToErrorLike(error.cause),
  };
}

function isWindowsAbsolutePath(path: string): boolean {
  return win32.isAbsolute(path);
}

function isPosixAbsolutePath(path: string): boolean {
  return posix.isAbsolute(path);
}

function formatStoryIndexPath(path: string): string {
  const withoutDotSlash = path.startsWith('./') ? path.slice(2) : path;
  const normalized = slash(normalize(withoutDotSlash));

  if (normalized === '.' || normalized.startsWith('../')) {
    return normalized;
  }

  return `./${normalized}`;
}

/**
 * Converts absolute or relative file paths into the same relative import-path format used by the
 * story index (`./src/Button.stories.tsx`). This is the storage format for module-graph service
 * state so static snapshots do not leak machine-specific filesystem roots.
 */
export function toStoryIndexPath(path: string, workingDir: string): string {
  if (isWindowsAbsolutePath(path)) {
    return formatStoryIndexPath(win32.relative(workingDir, path));
  }

  const slashPath = slash(path);
  if (isPosixAbsolutePath(slashPath)) {
    return formatStoryIndexPath(posix.relative(slash(workingDir), slashPath));
  }

  return formatStoryIndexPath(slashPath);
}

export function storyIndexPathToAbsolutePath(path: string, workingDir: string): string {
  if (isWindowsAbsolutePath(path) || isPosixAbsolutePath(slash(path))) {
    return slash(normalize(path));
  }

  return slash(normalize(posix.join(slash(workingDir), path)));
}

export function reverseIndexToStoriesByFile(
  index: ReverseIndex,
  workingDir: string
): StoriesByFileRecord {
  const result: StoriesByFileRecord = {};
  for (const [dep, stories] of index) {
    result[toStoryIndexPath(dep, workingDir)] = Object.fromEntries(
      Array.from(stories, ([storyFile, depth]) => [toStoryIndexPath(storyFile, workingDir), depth])
    );
  }
  return result;
}

export type GraphUpdatePayload = {
  storiesByFile: StoriesByFileRecord;
  bumpedStoryFiles: string[];
};

