    await service.commands.setReview(review);

    now = 5_000;
    onChange?.();
    await vi.waitFor(() => {
      expect(service.queries.current.get(undefined)).toEqual({ ...review, createdAt: 1_000 });
    });

    now = 12_000;
    onChange?.();
    await vi.waitFor(() => {
      expect(service.queries.current.get(undefined)).toEqual({
        ...review,
        createdAt: 1_000,
        stale: true,
      });
    });
  });
});

import type { StoryIndex } from 'storybook/internal/types';

import { OpenServiceUnknownStoryIdsError } from '../../../../server-errors.ts';
import { getService, registerService } from '../../server.ts';
import type { ModuleGraphService } from '../module-graph/definition.ts';
import { reviewServiceDef, type ReviewService } from './definition.ts';
import {
  applyAcceptPending,
  applyDismiss,
  applyMarkStale,
  applyPublishedReview,
} from './state-transitions.ts';

type SubscribeToModuleGraphChanges = (onChange: () => void) => () => void;

/**
 * Default subscription to the `core/module-graph` open service. The review goes stale when any
 * file in the story module graph changes (the service's revision only advances for in-graph
 * changes, so unrelated file edits never trip it). The `services` preset registers the module
 * graph before the review service, so the lookup succeeds synchronously here; if it's unavailable
 * (e.g. a builder without module-graph support), staleness simply never triggers.
 */
const defaultSubscribeToModuleGraphChanges: SubscribeToModuleGraphChanges = (onChange) => {
  try {
    const service = getService<ModuleGraphService>('core/module-graph', { internal: true });
    // Omit the input to watch the entire graph. The initial emission carries revision 0 (or the
    // current revision at subscribe time); only subsequent advances represent a change after the
    // review was cached.
    return service.queries.graphRevision.subscribe(undefined, ({ data: revision }) => {
      if (revision !== undefined && revision > 0) {
        onChange();
      }
    });
  } catch {
    // Module graph unavailable (e.g. builder without support); no staleness.
    return () => {};
  }
};

export interface RegisterReviewServiceOptions {
  getIndex: () => Promise<StoryIndex>;
  /** Override the module-graph-change subscription. Used by tests. */
  subscribeToModuleGraphChanges?: SubscribeToModuleGraphChanges;
}

/** Registers the stateful `core/review` service in the server realm. */
export function registerReviewService({
  getIndex,
  subscribeToModuleGraphChanges = defaultSubscribeToModuleGraphChanges,
}: RegisterReviewServiceOptions): ReviewService {
  const service = registerService(reviewServiceDef, {
    commands: {
      setReview: {
        handler: async (input, ctx) => {
          const { stale: _stale, createdAt: _createdAt, ...review } = input;
          const storyIds = [
            ...new Set(review.collections.flatMap((collection) => collection.storyIds)),
          ];
          const index = await getIndex();
          // Docs entries share the index but cannot be review slots: navigation and
          // previews resolve review entries as stories.
          const unknownIds = storyIds.filter((storyId) => index.entries[storyId]?.type !== 'story');
          if (unknownIds.length > 0) {
            throw new OpenServiceUnknownStoryIdsError({ unknownIds });
          }

          ctx.self.setState((state) => {
            applyPublishedReview(state, { ...review, createdAt: Date.now() });
          });
        },
      },
      acceptPending: {
        handler: async (_input, ctx) => {
          ctx.self.setState((state) => {
            applyAcceptPending(state);
          });
        },
      },
      markStale: {
        handler: async (_input, ctx) => {
          ctx.self.setState((state) => {
            applyMarkStale(state, Date.now());
          });
        },
      },
      dismissReview: {
        handler: async (_input, ctx) => {
          ctx.self.setState((state) => {
            applyDismiss(state);
          });
        },
      },
    },
  });

  // The subscription is process-lifetime by design: the service registers once per dev-server
  // process and there is no teardown phase to return it to. The grace window is enforced inside
  // `markStale`, so graph changes are always forwarded.
  subscribeToModuleGraphChanges(() => {
    void service.commands.markStale(undefined);
  });

  return service;
}

import type { ReviewState } from '../../../review/review-state.ts';
import { REVIEW_STALE_GRACE_MS, type ReviewServiceState } from './definition.ts';

/**
 * Pure state transitions for the `core/review` service, shared by the server registration and the
 * story-only manager double so the two cannot drift.
 *
 * Values are deep-copied through {@link toPlainReview} where they move between state slots:
 * commands read state through a deepSignal proxy, and assigning proxied values back into state
 * would leave wrappers that `structuredClone` cannot snapshot.
 */
export function toPlainReview(review: ReviewState): ReviewState {
  return {
    ...review,
    collections: review.collections.map((collection) => ({
      ...collection,
      storyIds: [...collection.storyIds],
    })),
    ...(review.changedFiles ? { changedFiles: [...review.changedFiles] } : {}),
  };
}

/**
 * Publishes a review: while one is current the update is deferred to `pending` so an in-progress
 * review isn't yanked; the latest update wins over any previously held one.
 */
export function applyPublishedReview(state: ReviewServiceState, review: ReviewState): void {
  if (state.current === null) {
    state.current = review;
    state.pending = null;
  } else {
    state.pending = review;
  }
}

/** Promotes the deferred update to current. No-op when nothing is pending. */
export function applyAcceptPending(state: ReviewServiceState): void {
  if (state.pending !== null) {
    state.current = toPlainReview(state.pending);
    state.pending = null;
  }
}

/**
 * Marks the current review stale once the grace window has passed. Replaces `current` with a plain
 * deep copy: a fresh reference keeps same-realm query subscribers reactive, and the deep copy
 * avoids leaving proxied nested arrays behind (which `structuredClone` cannot snapshot).
 */
export function applyMarkStale(state: ReviewServiceState, now: number): void {
  const current = state.current;
  if (
    current?.createdAt !== undefined &&
    !current.stale &&
    now >= current.createdAt + REVIEW_STALE_GRACE_MS
  ) {
    state.current = { ...toPlainReview(current), stale: true };
  }
}

/** Clears the current review and any deferred update. */
export function applyDismiss(state: ReviewServiceState): void {
  state.current = null;
  state.pending = null;
}

import * as v from 'valibot';

import { defineService } from 'storybook/open-service';
import type { ServiceInstanceOf } from '../../types.ts';
import type { StoryDocsPayload } from './types.ts';
import { storyDocsQueryStaticPath } from './paths.ts';

const storyDocsInputSchema = v.object({ id: v.string() });

const storyDocsErrorSchema = v.object({
  name: v.string(),
  message: v.string(),
});

const storyDocSchema = v.object({
  id: v.string(),
  name: v.string(),
  snippet: v.optional(v.string()),
  description: v.optional(v.string()),
  summary: v.optional(v.string()),
  warning: v.optional(v.string()),
  error: v.optional(storyDocsErrorSchema),
});

const storyDocsPayloadSchema = v.object({
  id: v.string(),
  name: v.string(),
  path: v.string(),
  import: v.optional(v.string()),
  stories: v.record(v.string(), storyDocSchema),
  error: v.optional(storyDocsErrorSchema),
});

const storyDocsOutputSchema = v.optional(storyDocsPayloadSchema);

export type StoryDocsServiceState = {
  /** Extracted story docs keyed by component id. Populated by the `extractStoryDocs` command. */
  components: Record<string, StoryDocsPayload>;
};

/**
 * Definition for the `core/story-docs` open service.
 *
 * Carries per-story snippets, descriptions, and file-level import statements keyed by component
 * id. Component prop docgen lives in `core/docgen`.
 */
export const storyDocsServiceDef = defineService({
  id: 'core/story-docs',
  internal: true,
  description: 'Story documentation (snippets, descriptions, imports) keyed by component id.',
  initialState: { components: {} } as StoryDocsServiceState,
  queries: {
    storyDocs: {
      description:
        'Returns the story-docs payload for one component id, or undefined when not loaded.',
      input: storyDocsInputSchema,
      output: storyDocsOutputSchema,
      handler: (input, ctx) =>
        Object.hasOwn(ctx.self.state.components, input.id)
          ? ctx.self.state.components[input.id]
          : undefined,
      load: async (input, ctx) => {
        await ctx.self.commands.extractStoryDocs(input);
      },
      staticPath: (input) => storyDocsQueryStaticPath(input.id),
    },
    storyDocsForAllComponents: {
      description: 'Returns story-docs payloads for every component in the story index.',
      input: v.void(),
      output: v.record(v.string(), storyDocsPayloadSchema),
      handler: (_input, ctx) => ctx.self.state.components,
      load: async (_input, ctx) => {
        await ctx.self.commands.extractAllStoryDocs(undefined);
      },
    },
  },
  commands: {
    extractStoryDocs: {
      description:
        'Resolves the story entry for a component id, runs the registered provider chain, writes the result into state, and returns it (or undefined when no provider produced story docs).',
      input: storyDocsInputSchema,
      output: storyDocsOutputSchema,
    },
    extractAllStoryDocs: {
      description:
        'Extracts story docs for every component id in the story index by invoking `extractStoryDocs` for each.',
      input: v.undefined(),
      output: v.void(),
    },
  },
});

export type StoryDocsService = ServiceInstanceOf<typeof storyDocsServiceDef>;

