            type: { name: 'bool' },
            required: true,
          },
          size: {
            type: { name: 'union', value: ['small', 'medium', 'large'] },
            defaultValue: { value: 'medium', computed: false },
          },
        },
      },
    };

    const result = formatComponentManifest(manifest);

    expect(result).toMatchInlineSnapshot(`
			"# Button

			ID: button

			## Props

			\`\`\`
			export type Props = {
			  /**
			    The button variant
			  */
			  variant?: string = primary;
			  disabled: bool;
			  size: union = medium;
			}
			\`\`\`"
		`);
  });
});

