import type { DocgenPayload } from '../../services/docgen/types.ts';
import type { StoryDocsPayload } from '../../services/story-docs/types.ts';
import type { DocsClassification } from './classify-services.ts';

export type MdxDoc = {
  id: string;
  name: string;
  path?: string;
  title?: string;
  content?: string;
  summary?: string;
  error?: { name: string; message: string };
};

export type MdxPayload = {
  id: string;
  name: string;
  docs: Record<string, MdxDoc>;
};

/**
 * Picks a component's attached MDX docs out of its payload, shared by the Markdown and JSON docs
 * paths so the two cannot drift. `undefined` when the component has no attached docs, letting
 * callers omit the key entirely.
 */
export function selectAttachedDocs(
  classification: DocsClassification,
  id: string,
  mdx: MdxPayload | undefined
): Record<string, MdxDoc> | undefined {
  const attached = classification.attachedDocsByComponent.get(id) ?? [];
  if (attached.length === 0 || !mdx?.docs) {
    return undefined;
  }

  const docs: Record<string, MdxDoc> = {};
  for (const docsId of attached) {
    const doc = mdx.docs[docsId];
    if (doc) {
      docs[docsId] = doc;
    }
  }
  return docs;
}

export type DocsListResult = {
  components: Array<{
    id: string;
    name: string;
    summary?: string;
    storyIds?: string[];
  }>;
  docs: Array<{
    id: string;
    name: string;
    title?: string;
    summary?: string;
  }>;
};

export type DocsShowResult =
  | {
      kind: 'component';
      id: string;
      name: string;
      path?: string;
      description?: string;
      summary?: string;
      import?: string;
      jsDocTags?: Record<string, string[]>;
      reactDocgen?: unknown;
      reactDocgenTypescript?: unknown;
      reactComponentMeta?: unknown;
      stories?: Array<{
        id?: string;
        name: string;
        description?: string;
        summary?: string;
        snippet?: string;
        error?: { name: string; message: string };
      }>;
      subcomponents?: Record<string, unknown>;
      docs?: Record<string, MdxDoc>;
      error?: { name: string; message: string };
    }
  | {
      kind: 'docs';
      id: string;
      name: string;
      title?: string;
      path?: string;
      content?: string;
      summary?: string;
      error?: { name: string; message: string };
    }
  | { kind: 'not-found'; id: string };

export type DocsShowStoryResult =
  | {
      kind: 'story';
      component: { id: string; name: string; import?: string };
      story: {
        id?: string;
        name: string;
        description?: string;
        summary?: string;
        snippet?: string;
        error?: { name: string; message: string };
      };
    }
  | { kind: 'component-not-found'; componentId: string }
  | {
      kind: 'story-not-found';
      componentId: string;
      storyName: string;
      availableStoryNames: string[];
    };

function summaryOf(item: { summary?: string; description?: string }): string | undefined {
  return item.summary ?? item.description;
}

/** Builds the transport-neutral `docs.list` payload from settled dependency data. */
export function mapDocsList(params: {
  classification: DocsClassification;
  allDocgen: Record<string, DocgenPayload | undefined>;
  allStoryDocs: Record<string, StoryDocsPayload | undefined>;
  allMdx: Record<string, MdxPayload | undefined>;
  withStoryIds: boolean;
}): DocsListResult {
  const { classification, allDocgen, allStoryDocs, allMdx, withStoryIds } = params;

  const components = classification.componentIds.map((id) => {
    const payload = allDocgen[id];
    const component: DocsListResult['components'][number] = {
      id,
      name: payload?.name ?? id,
    };
    const summary = summaryOf(payload ?? {});
    if (summary !== undefined) {
      component.summary = summary;
    }
    if (withStoryIds && classification.storyBasedIds.has(id)) {
      const stories = allStoryDocs[id]?.stories;
      component.storyIds = stories
        ? Object.values(stories)
            .map((story) => story.id)
            .filter((storyId): storyId is string => typeof storyId === 'string')
        : [];
    }
    return component;
  });

  const docs = [...classification.unattachedDocs.entries()].map(([docId, name]) => {
    const payload = allMdx[docId]?.docs?.[docId];
    const doc: DocsListResult['docs'][number] = {
      id: docId,
      name,
    };
    if (payload?.title !== undefined) {
      doc.title = payload.title;
    }
    if (payload?.summary !== undefined) {
      doc.summary = payload.summary;
    }
    return doc;
  });

  return { components, docs };
}

/** Maps story-docs entries to the transport-neutral story shape, omitting absent fields. */
export function mapStoryDocsEntries(stories: NonNullable<StoryDocsPayload['stories']>) {
  return Object.values(stories).map((story) => ({
    ...(story.id !== undefined ? { id: story.id } : {}),
    name: story.name,
    ...(story.description !== undefined ? { description: story.description } : {}),
    ...(story.summary !== undefined ? { summary: story.summary } : {}),
    ...(story.snippet !== undefined ? { snippet: story.snippet } : {}),
    ...(story.error !== undefined ? { error: story.error } : {}),
  }));
}

/** A story-docs import statement wins over docgen's; either may be absent. */
export function resolveImportStatement(
  storyDocs?: StoryDocsPayload,
  docgen?: DocgenPayload
): string | undefined {
  return typeof storyDocs?.import === 'string'
    ? storyDocs.import
    : typeof docgen?.import === 'string'
      ? docgen.import
      : undefined;
}

/** Builds the transport-neutral `docs.show` payload for one id. */
export function mapDocsShow(params: {
  id: string;
  classification: DocsClassification;
  docgen?: DocgenPayload;
  storyDocs?: StoryDocsPayload;
  mdx?: MdxPayload;
}): DocsShowResult {
  const { id, classification, docgen, storyDocs, mdx } = params;

  if (classification.unattachedDocs.has(id)) {
    const doc = mdx?.docs?.[id];
    if (!doc) {
      return { kind: 'not-found', id };
    }
    return {
      kind: 'docs',
      id: doc.id,
      name: doc.name,
      ...(doc.title !== undefined ? { title: doc.title } : {}),
      ...(doc.path !== undefined ? { path: doc.path } : {}),
      ...(doc.content !== undefined ? { content: doc.content } : {}),
      ...(doc.summary !== undefined ? { summary: doc.summary } : {}),
      ...(doc.error !== undefined ? { error: doc.error } : {}),
    };
  }

  if (!classification.componentIds.includes(id)) {
    return { kind: 'not-found', id };
  }

  const docs = selectAttachedDocs(classification, id, mdx);

  const stories = storyDocs?.stories ? mapStoryDocsEntries(storyDocs.stories) : undefined;

  const importStatement = resolveImportStatement(storyDocs, docgen);

  return {
    kind: 'component',
    id,
    name: docgen?.name ?? id,
    ...(docgen?.path !== undefined ? { path: docgen.path } : {}),
    ...(docgen?.description !== undefined ? { description: docgen.description } : {}),
    ...(docgen?.summary !== undefined ? { summary: docgen.summary } : {}),
    ...(importStatement !== undefined ? { import: importStatement } : {}),
    ...(docgen?.jsDocTags !== undefined ? { jsDocTags: docgen.jsDocTags } : {}),
    ...(docgen?.reactDocgen !== undefined ? { reactDocgen: docgen.reactDocgen } : {}),
    ...(docgen?.reactDocgenTypescript !== undefined
      ? { reactDocgenTypescript: docgen.reactDocgenTypescript }
      : {}),
    ...(docgen?.reactComponentMeta !== undefined
      ? { reactComponentMeta: docgen.reactComponentMeta }
      : {}),
    ...(stories ? { stories } : {}),
    ...(docgen?.subcomponents !== undefined ? { subcomponents: docgen.subcomponents } : {}),
    ...(docs && Object.keys(docs).length > 0 ? { docs } : {}),
    ...(docgen?.error !== undefined ? { error: docgen.error } : {}),
  };
}

/** Builds the transport-neutral `docs.showStory` payload. */
export function mapDocsShowStory(params: {
  componentId: string;
  storyName: string;
  show: DocsShowResult;
}): DocsShowStoryResult {
  const { componentId, storyName, show } = params;

  if (show.kind !== 'component') {
    return { kind: 'component-not-found', componentId };
  }

  const stories = show.stories ?? [];
  const story = stories.find((entry) => entry.name === storyName);
  if (!story) {
    return {
      kind: 'story-not-found',
      componentId,
      storyName,
      availableStoryNames: stories.map((entry) => entry.name),
    };
  }

  return {
    kind: 'story',
    component: {
      id: show.id,
      name: show.name,
      ...(show.import !== undefined ? { import: show.import } : {}),
    },
    story,
  };
}

import { beforeEach, describe, expect, it, vi } from 'vitest';
import * as v from 'valibot';

import type { ToolsetCtx } from '../../toolset-definition.ts';
import { OpenServiceMissingOriginError } from '../../../../server-errors.ts';
import { reviewToolset } from './definition.ts';

const input = {
  title: 'Button tweaks',
  description: 'Check primary',
  collections: [
    {
      title: 'Primary',
      rationale: 'edited',
      storyIds: ['button--primary'],
    },
  ],
  changedFiles: ['src/Button.tsx'],
};

const setReview = vi.fn();
let ctx: ToolsetCtx;
let serviceError: Error | undefined;

function createReview(
  overrides: Partial<v.InferInput<typeof reviewToolset.methods.create.schema>> = {}
) {
  return reviewToolset.methods.create.handler(
    v.parse(reviewToolset.methods.create.schema, { ...input, ...overrides }),
    ctx
  );
}

describe('review API', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    serviceError = undefined;
    setReview.mockImplementation(async () => {
      if (serviceError) {
        throw serviceError;
      }
    });
    ctx = {
      consumer: 'cli',
      origin: 'http://localhost:6006/',
      format: 'markdown',
      getService: vi.fn(() => ({ commands: { setReview } })) as ToolsetCtx['getService'],
    };
  });

  it('rejects with a missing-origin error when no server origin is configured', async () => {
    ctx.origin = undefined;

    await expect(createReview()).rejects.toBeInstanceOf(OpenServiceMissingOriginError);
    expect(setReview).not.toHaveBeenCalled();
  });

  it('propagates service errors unchanged', async () => {
    serviceError = new Error('review service unavailable');

    await expect(createReview()).rejects.toBe(serviceError);
  });

  it('sets review state and returns Markdown by default', async () => {
    await expect(createReview()).resolves.toBe(
      'Review created: http://localhost:6006/?path=/review/'
    );
    expect(setReview).toHaveBeenCalledWith(input);
    expect(ctx.getService).toHaveBeenCalledWith('core/review', { internal: true });
  });

  it('adds the user-facing instruction only for the MCP Markdown response', async () => {
    const cliResult = await createReview();
    ctx.consumer = 'mcp';
    const mcpResult = await createReview();

    expect(cliResult).not.toContain('Show this review URL');
    expect(mcpResult).toBe(
      `${cliResult}\n\nShow this review URL to the user in your final response.`
    );
  });

  it('returns structured data when the adapter requests JSON', async () => {
    ctx.format = 'json';

    await expect(createReview()).resolves.toEqual({
      reviewUrl: 'http://localhost:6006/?path=/review/',
    });
    expect(setReview).toHaveBeenCalledWith(input);
  });
});

import * as v from 'valibot';

import { OpenServiceMissingOriginError } from '../../../../server-errors.ts';
import { defineToolset } from '../../toolset-definition.ts';
import { reviewStateSchema, type ReviewService } from '../../services/review/definition.ts';

const reviewCreateInputSchema = v.object({
  ...v.omit(reviewStateSchema, ['createdAt', 'stale', 'changedFiles']).entries,
  changedFiles: v.pipe(
    v.array(v.string()),
    v.description(
      'Changed file paths, most central first. Pass an empty array when nothing changed.'
    )
  ),
});

export const reviewToolset = defineToolset({
  id: 'review',
  description: 'Create a curated Storybook review.',
  methods: {
    create: {
      schema: reviewCreateInputSchema,
      description: 'Validates story ids, publishes review state, and returns the review page URL.',
      handler: async (review, ctx) => {
        if (!ctx.origin) {
          throw new OpenServiceMissingOriginError({
            toolsetId: 'review',
            methodName: 'create',
          });
        }

        await ctx
          .getService<ReviewService>('core/review', { internal: true })
          .commands.setReview(review);

        const reviewUrl = `${ctx.origin.replace(/\/$/, '')}/?path=/review/`;
        if (ctx.format === 'json') {
          return { reviewUrl };
        }

        const markdown = `Review created: ${reviewUrl}`;
        return ctx.consumer === 'mcp'
          ? `${markdown}\n\nShow this review URL to the user in your final response.`
          : markdown;
      },
    },
  },
});

export type ReviewToolset = typeof reviewToolset;

import { describe, expect, it } from 'vitest';

import type { StoryIndex } from 'storybook/internal/types';

import type { StatusesByStoryIdAndTypeId } from '../../../status-store/index.ts';
import { CHANGE_DETECTION_STATUS_TYPE_ID } from '../../../status-store/index.ts';
import { getChangedStories } from './changed.ts';

const index: StoryIndex = {
  v: 5,
  entries: {
    'button--primary': {
      type: 'story',
      subtype: 'story',
      id: 'button--primary',
      name: 'Primary',
      title: 'Button',
      importPath: './src/Button.stories.tsx',
      tags: ['story'],
    },
    'button--secondary': {
      type: 'story',
      subtype: 'story',
      id: 'button--secondary',
      name: 'Secondary',
      title: 'Button',
      importPath: './src/Button.stories.tsx',
      tags: ['story'],
    },
    'input--default': {
      type: 'story',
      subtype: 'story',
      id: 'input--default',
      name: 'Default',
      title: 'Input',
      importPath: './src/Input.stories.tsx',
      tags: ['story'],
    },
    'card--basic': {
      type: 'story',
      subtype: 'story',
      id: 'card--basic',
      name: 'Basic',
      title: 'Card',
      importPath: './src/Card.stories.tsx',
      tags: ['story'],
    },
  },
};

function status(
  storyId: string,
  value:
    | 'status-value:new'
    | 'status-value:modified'
    | 'status-value:affected'
    | 'status-value:success'
) {
  return {
    value,
    typeId: CHANGE_DETECTION_STATUS_TYPE_ID,
    storyId,
    title: 'Change detection',
    description: '',
  };
}

describe('getChangedStories', () => {
  it('filters to new/modified/affected and ignores other status values', () => {
    const statuses: StatusesByStoryIdAndTypeId = {
      'button--primary': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('button--primary', 'status-value:new'),
      },
      'input--default': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('input--default', 'status-value:success'),
      },
    };

    const result = getChangedStories({ statuses, index });

    expect(result.stories.map((s) => s.storyId)).toEqual(['button--primary']);
    expect(result.counts).toEqual({ new: 1, modified: 0, affected: 0 });
  });

  it('sorts by priority new → modified → affected, then storyId', () => {
    const statuses: StatusesByStoryIdAndTypeId = {
      'card--basic': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('card--basic', 'status-value:affected'),
      },
      'button--secondary': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('button--secondary', 'status-value:new'),
      },
      'input--default': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('input--default', 'status-value:modified'),
      },
      'button--primary': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('button--primary', 'status-value:new'),
      },
    };

    const result = getChangedStories({ statuses, index });

    expect(result.stories.map((s) => s.storyId)).toEqual([
      'button--primary',
      'button--secondary',
      'input--default',
      'card--basic',
    ]);
    expect(result.stories.map((s) => s.statusValue)).toEqual([
      'status-value:new',
      'status-value:new',
      'status-value:modified',
      'status-value:affected',
    ]);
  });

  it('computes counts for each status bucket', () => {
    const statuses: StatusesByStoryIdAndTypeId = {
      'button--primary': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('button--primary', 'status-value:new'),
      },
      'button--secondary': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('button--secondary', 'status-value:modified'),
      },
      'input--default': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('input--default', 'status-value:affected'),
      },
      'card--basic': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('card--basic', 'status-value:affected'),
      },
    };

    const result = getChangedStories({
      statuses,
      index,
    });

    expect(result.counts).toEqual({ new: 1, modified: 1, affected: 2 });
  });

  it('drops statuses whose storyId is missing from the index', () => {
    const statuses: StatusesByStoryIdAndTypeId = {
      'ghost--story': {
        [CHANGE_DETECTION_STATUS_TYPE_ID]: status('ghost--story', 'status-value:new'),
      },
    };

    const result = getChangedStories({ statuses, index });

    expect(result.stories).toEqual([]);
    expect(result.counts).toEqual({ new: 0, modified: 0, affected: 0 });
  });

  it('returns empty stories when nothing changed', () => {
    const result = getChangedStories({
      statuses: {},
      index,
    });

    expect(result).toEqual({
      stories: [],
      counts: { new: 0, modified: 0, affected: 0 },
    });
  });
});

import type { StoryIndex } from 'storybook/internal/types';

import type {
  Status,
  StatusesByStoryIdAndTypeId,
  StatusValue,
} from '../../../status-store/index.ts';
import { CHANGE_DETECTION_STATUS_TYPE_ID } from '../../../status-store/index.ts';
import type { ChangedStoriesOutput, ChangeStatusValue } from './definition.ts';

const INCLUDED_STATUS_VALUES = new Set<ChangeStatusValue>([
  'status-value:new',
  'status-value:modified',
  'status-value:affected',
]);

function isChangeStatusValue(value: StatusValue): value is ChangeStatusValue {
  return INCLUDED_STATUS_VALUES.has(value as ChangeStatusValue);
}

function statusPriority(statusValue: ChangeStatusValue): number {
  if (statusValue === 'status-value:new') return 0;
  if (statusValue === 'status-value:modified') return 1;
  return 2;
}

export type ChangedStoriesParams = {
  /** Change-detection statuses keyed by storyId → typeId → status. */
  statuses: StatusesByStoryIdAndTypeId;
  index: StoryIndex;
};

export type ChangedStoriesResult = Omit<ChangedStoriesOutput, 'unreachableFiles'>;

/**
 * Filters change-detection statuses to new/modified/affected, enriches from the story index,
 * and sorts by priority then storyId.
 */
export function getChangedStories({ statuses, index }: ChangedStoriesParams): ChangedStoriesResult {
  const changedFromStatusStore: Status[] = [];
  for (const byType of Object.values(statuses)) {
    const status = byType?.[CHANGE_DETECTION_STATUS_TYPE_ID];
    if (status?.value && isChangeStatusValue(status.value)) {
      changedFromStatusStore.push(status);
    }
  }

  const stories = changedFromStatusStore.flatMap(({ storyId, value }) => {
    const entry = index.entries[storyId];
    if (!entry || !isChangeStatusValue(value)) {
      return [];
    }
    return [
      {
        storyId,
        statusValue: value,
        title: entry.title,
        name: entry.name,
        importPath: entry.importPath,
      },
    ];
  });

  stories.sort((a, b) => {
    const priorityDelta = statusPriority(a.statusValue) - statusPriority(b.statusValue);
    return priorityDelta !== 0 ? priorityDelta : a.storyId.localeCompare(b.storyId);
  });

  const counts = {
    new: stories.filter((story) => story.statusValue === 'status-value:new').length,
    modified: stories.filter((story) => story.statusValue === 'status-value:modified').length,
    affected: stories.filter((story) => story.statusValue === 'status-value:affected').length,
  };

  return { stories, counts };
}

