import type { StoryIndex } from 'storybook/internal/types';

import { buildArgsParam } from '../../../../router/utils.ts';
import type { PreviewStoriesOutput } from './definition.ts';
import { findStoryIds } from './find-story-ids.ts';
import type { StoryInput } from './story-input.ts';

export type PreviewStoriesParams = {
  origin: string;
  index: StoryIndex;
  stories: StoryInput[];
};

/**
 * Resolves story selectors to preview URLs (and per-input errors).
 *
 * Pure helper: callers supply origin + index; no I/O.
 */
export function previewStories({
  origin,
  index,
  stories,
}: PreviewStoriesParams): PreviewStoriesOutput {
  const resolvedStories = findStoryIds(index, stories);
  const result: PreviewStoriesOutput['stories'] = [];

  for (const story of resolvedStories) {
    if ('errorMessage' in story) {
      result.push({
        input: story.input,
        error: story.errorMessage,
      });
      continue;
    }

    const indexEntry = story.entry;
    let previewUrl = `${origin}/?path=/story/${indexEntry.id}`;

    const argsParam = buildArgsParam({}, story.input.props ?? {});
    if (argsParam) {
      previewUrl += `&args=${argsParam}`;
    }

    const globalsParam = buildArgsParam({}, story.input.globals ?? {});
    if (globalsParam) {
      previewUrl += `&globals=${globalsParam}`;
    }

    result.push({
      title: indexEntry.title,
      name: indexEntry.name,
      previewUrl,
    });
  }

  return { stories: result };
}

import * as v from 'valibot';

/**
 * Shared story selector used by the stories and test APIs.
 *
 * Prefer `{ storyId }` unless the caller already has a concrete story-file path and export name.
 */
export const storyInputSchema = v.union([
  v.object({
    exportName: v.pipe(
      v.string(),
      v.description('Export name of the story from the story file (for example "Primary").')
    ),
    explicitStoryName: v.pipe(
      v.optional(v.string()),
      v.description('Story `name` when it differs from the export name.')
    ),
    absoluteStoryPath: v.pipe(
      v.string(),
      v.description('Absolute path to the story file, used with exportName.')
    ),
    props: v.pipe(
      v.optional(v.record(v.string(), v.any())),
      v.description('Optional story args/props overrides.')
    ),
    globals: v.pipe(
      v.optional(v.record(v.string(), v.any())),
      v.description('Optional Storybook globals (theme, locale, viewport, …).')
    ),
  }),
  v.object({
    storyId: v.pipe(
      v.string(),
      v.description('Full Storybook story id (for example "button--primary").')
    ),
    props: v.pipe(
      v.optional(v.record(v.string(), v.any())),
      v.description('Optional story args/props overrides.')
    ),
    globals: v.pipe(
      v.optional(v.record(v.string(), v.any())),
      v.description('Optional Storybook globals (theme, locale, viewport, …).')
    ),
  }),
]);

export const storyInputArraySchema = v.array(storyInputSchema);

export type StoryInput = v.InferOutput<typeof storyInputSchema>;

