  }),
]);

export type TestRunResult = v.InferOutput<typeof testRunResultSchema>;
export type TestRunOutput = v.InferOutput<typeof testRunOutputSchema>;

export type CreateTestToolsetOptions = {
  channel: TestChannel;
  storyIndex: StoryIndexAccess;
};

/**
 * Creates the public test API. Each registration owns a queue because addon-vitest supports one
 * live test run at a time.
 */
export function createTestToolset({ channel, storyIndex }: CreateTestToolsetOptions) {
  const queue = createAsyncQueue();

  return defineToolset({
    id: 'test',
    description: 'Run Storybook story tests via addon-vitest.',
    methods: {
      run: {
        schema: v.object({
          stories: v.optional(
            v.pipe(
              storyInputArraySchema,
              v.description('Stories to test. Omit to run all available stories.')
            )
          ),
          a11y: v.optional(
            v.pipe(
              v.boolean(),
              v.description('Whether to include accessibility tests. Defaults to true.')
            ),
            true
          ),
        }),
        description:
          'Runs story tests for the given selectors, or all stories when stories is omitted.',
        handler: async (input, ctx) => {
          const done = await queue.wait();
          try {
            const result = await runStoryTests({
              channel,
              getIndex: storyIndex.getIndex,
              stories: input.stories,
              a11y: input.a11y,
            });
            return ctx.format === 'json' ? result : formatTestRun(result);
          } finally {
            done();
          }
        },
      },
    },
  });
}

export type TestToolset = ReturnType<typeof createTestToolset>;

import type { TestRunOutput } from './definition.ts';

/** Formats a test run result as a compact summary for humans and agents. */
export function formatTestRun(output: TestRunOutput): string {
  switch (output.status) {
    case 'no-stories':
      return '# No stories matched\nNo story tests were run.';
    case 'error':
      return `# Test run failed\n${output.error.message}`;
    case 'cancelled':
      return '# Test run cancelled\nThe test run was cancelled.';
    case 'completed': {
      const { componentTestCount, a11yCount, totalTestCount } = output.result;
      const total =
        totalTestCount ??
        componentTestCount.success +
          componentTestCount.error +
          a11yCount.success +
          a11yCount.warning +
          a11yCount.error;

      return [
        '# Test run completed',
        `- Total tests: ${total}`,
        `- Component tests: ${componentTestCount.success} passed, ${componentTestCount.error} failed`,
        `- Accessibility tests: ${a11yCount.success} passed, ${a11yCount.warning} warnings, ${a11yCount.error} failed`,
      ].join('\n');
    }
  }
}

